function flattenAirtable(items) {
  const out = [];
  for (const item of items || []) {
    const records = item && item.json && Array.isArray(item.json.records) ? item.json.records : [];
    for (const record of records) {
      out.push(Object.assign({ record_id: record.id }, record.fields || {}));
    }
  }
  return out;
}

function configMap(rows) {
  const map = {};
  for (const row of rows || []) {
    if (row.key) map[row.key] = row.value;
  }
  return map;
}

function toArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function normalizeText(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function normalizeEmail(value) {
  return normalizeText(value).toLowerCase();
}

function normalizeBool(value) {
  if (value === true) return true;
  if (value === false) return false;
  return ["true", "1", "yes", "y"].includes(normalizeText(value).toLowerCase());
}

function buildConfig(configRows) {
  const config = {};
  for (const row of toArray(configRows)) {
    const key = normalizeText(row.key);
    if (key) config[key] = normalizeText(row.value);
  }
  return config;
}

function hashHex(value) {
  let hash = 2166136261;
  const text = normalizeText(value);
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).toUpperCase().padStart(8, "0");
}

function parseEmailAddress(value) {
  const text = normalizeText(value);
  const angleMatch = text.match(/<([^<>@\s]+@[^<>@\s]+)>/);
  if (angleMatch) return normalizeEmail(angleMatch[1]);
  const bareMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return bareMatch ? normalizeEmail(bareMatch[0]) : normalizeEmail(text);
}

function extractRefToken(value) {
  const match = normalizeText(value).match(/\[?(R-[0-9A-F]{4})\]?/i);
  return match ? match[1].toUpperCase() : "";
}

function stripHtml(value) {
  return normalizeText(value)
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+\n/g, "\n")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function stripQuotedReply(value) {
  let text = stripHtml(value).replace(/\r\n/g, "\n");
  text = text.split(/\nOn .+ wrote:\s*$/im)[0];
  text = text.split(/\n-{2,}\s*Original Message\s*-{2,}/i)[0];
  text = text.split(/\nFrom:\s.+\nSent:\s.+\nTo:\s.+/i)[0];
  text = text
    .split("\n")
    .filter((line) => !normalizeText(line).startsWith(">"))
    .join("\n");
  text = text.split(/\n--\s*$/m)[0];
  text = text.split(/\nSent from my /i)[0];
  text = text.split(/\nThis message and any attachments/i)[0];
  return text.replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();
}

function hasManualReplyPayload(body) {
  return Boolean(
    normalizeText(body.reply_text || body.text || body.body || body.message) ||
    normalizeText(body.subject) ||
    normalizeText(body.from_email || body.from || body.sender),
  );
}

function headerValue(headers, name) {
  const target = normalizeText(name).toLowerCase();
  if (!headers) return "";
  if (Array.isArray(headers)) {
    const found = headers.find((header) => normalizeText(header.name).toLowerCase() === target);
    return found ? normalizeText(found.value) : "";
  }
  if (typeof headers === "object") {
    const key = Object.keys(headers).find((candidate) => normalizeText(candidate).toLowerCase() === target);
    return key ? normalizeText(headers[key]) : "";
  }
  return "";
}

function isAutoReply(reply) {
  const subject = normalizeText(reply.subject);
  const body = normalizeText(reply.reply_text);
  const headers = reply.headers || {};
  const autoSubmitted = headerValue(headers, "Auto-Submitted");
  const xAutoreply = headerValue(headers, "X-Autoreply");
  const precedence = headerValue(headers, "Precedence");

  if (autoSubmitted && !/^no$/i.test(autoSubmitted)) return true;
  if (xAutoreply) return true;
  if (/^(bulk|auto_reply|list)$/i.test(precedence)) return true;
  if (/\b(out of office|automatic reply|auto-?reply|delivery status notification|undeliverable|mail delivery failed)\b/i.test(subject)) return true;
  if (/\b(out of the office|out of office|limited access to email|currently away|automatic reply)\b/i.test(body)) return true;
  return false;
}

function containsQuestion(replyText) {
  const text = normalizeText(replyText);
  const questionWord = /\b(what|when|who|whom|whose|which|where|why|how|can|could|will|would|should|do|does|did|is|are|any chance|possible)\b/i;
  return /\?/.test(text) && questionWord.test(text);
}

function eventIdForReply(reply) {
  const messageId = normalizeText(reply.message_id || reply.id);
  if (messageId) return `reply-${messageId.replace(/[^A-Za-z0-9_.:-]/g, "-").slice(0, 96)}`;
  return `reply-${hashHex(`${reply.from_email}|${reply.subject}|${reply.reply_text}`)}`;
}

function findExistingEvent(logRows, eventId) {
  return toArray(logRows).some((row) => normalizeText(row.event_id) === eventId);
}

function matchLease(reply, leases) {
  const token = extractRefToken(`${reply.subject || ""} ${reply.reply_text || ""}`);
  if (token) {
    const tokenMatch = toArray(leases).find((lease) => normalizeText(lease.ref_token).toUpperCase() === token);
    if (tokenMatch) return { lease: tokenMatch, match_method: "ref_token", ref_token: token };
  }

  const fromEmail = normalizeEmail(reply.from_email);
  if (fromEmail) {
    const emailMatches = toArray(leases).filter((lease) => normalizeEmail(lease.email) === fromEmail);
    const sentFirst = emailMatches.find((lease) => ["SENT", "AT_RISK", "STAYING"].includes(normalizeText(lease.status).toUpperCase()));
    if (sentFirst) return { lease: sentFirst, match_method: "email", ref_token: normalizeText(sentFirst.ref_token) };
    if (emailMatches.length === 1) return { lease: emailMatches[0], match_method: "email", ref_token: normalizeText(emailMatches[0].ref_token) };
  }

  return { lease: null, match_method: "unmatched", ref_token: token };
}

function normalizeGmailMessage(message) {
  const headers = message.headers || message.payload?.headers || {};
  const subject = normalizeText(message.subject || headerValue(headers, "Subject"));
  const fromEmail = parseEmailAddress(message.from || headerValue(headers, "From"));
  const replyText = stripQuotedReply(message.textPlain || message.text || message.snippet || message.textHtml || message.html || "");
  return {
    source: "gmail",
    message_id: normalizeText(message.id || message.messageId),
    thread_id: normalizeText(message.threadId || message.thread_id),
    from_email: fromEmail,
    subject,
    reply_text: replyText,
    headers,
    raw: message,
  };
}

function normalizeManualReply(body) {
  const replyText = stripQuotedReply(body.reply_text || body.text || body.body || body.message || "");
  return {
    source: "manual",
    message_id: normalizeText(body.message_id || body.id || body.fixture_id),
    thread_id: normalizeText(body.thread_id),
    from_email: parseEmailAddress(body.from_email || body.from || body.sender || ""),
    subject: normalizeText(body.subject || ""),
    reply_text: replyText,
    headers: body.headers || {},
    suppress_alerts: normalizeBool(body.suppress_alerts),
    raw: body,
  };
}

function noReplyResult(config, sourceMode) {
  return {
    ok: true,
    action: "check_replies",
    source: sourceMode || "gmail",
    processed_count: 0,
    alerted_count: 0,
    duplicate_count: 0,
    no_signal_count: 0,
    unmatched_count: 0,
    message: "No unprocessed replies found.",
    board_url: "http://localhost:5678/webhook/board",
    _terminal: true,
    _skip_log: true,
    _skip_lease_update: true,
  };
}

function prepareReplyWorkItem(reply, config, leases, logRows) {
  const eventId = eventIdForReply(reply);
  const duplicate = findExistingEvent(logRows, eventId);
  const base = {
    ok: true,
    action: "check_replies",
    source: reply.source,
    event_id: eventId,
    reply,
    config,
    board_url: "http://localhost:5678/webhook/board",
    _processed_label_id: normalizeText(config.gmail_processed_label_id || config.processed_label_id || reply.processed_label_id),
    _gmail_message_id: reply.source === "gmail" ? normalizeText(reply.message_id) : "",
    _suppress_alerts: normalizeBool(reply.suppress_alerts),
  };

  if (!normalizeText(reply.reply_text) && !normalizeText(reply.subject)) {
    return noReplyResult(config, reply.source);
  }

  if (duplicate) {
    return {
      ...base,
      processed_count: 0,
      alerted_count: 0,
      duplicate_count: 1,
      no_signal_count: 0,
      unmatched_count: 0,
      duplicate: true,
      message: "Reply already processed.",
      _terminal: true,
      _skip_log: true,
      _skip_lease_update: true,
    };
  }

  const match = matchLease(reply, leases);
  if (!match.lease) {
    const classification = {
      intent: "UNMATCHED",
      grievance_present: false,
      grievance_summary: "Reply could not be matched to a lease.",
      grievance_category: "NONE",
      urgency: "HIGH",
      compliance_flag: "NONE",
      suggested_human_action: "Find the tenant manually before replying.",
      confidence: "LOW",
      contains_question: containsQuestion(reply.reply_text),
      requires_human: true,
    };
    return finalizeRoute({ ...base, lease: {}, match_method: "unmatched" }, classification, new Date().toISOString(), "UNMATCHED_REPLY");
  }

  const matched = { ...base, lease: match.lease, match_method: match.match_method, ref_token: match.ref_token };
  if (isAutoReply(reply)) {
    const classification = {
      intent: "NO_SIGNAL",
      grievance_present: false,
      grievance_summary: "",
      grievance_category: "NONE",
      urgency: "LOW",
      compliance_flag: "NONE",
      suggested_human_action: "No action needed.",
      confidence: "HIGH",
      contains_question: false,
      requires_human: false,
    };
    return finalizeRoute(matched, classification, new Date().toISOString(), "NO_SIGNAL");
  }

  if (shouldUseFastDeterministicRoute(reply.reply_text)) {
    const classification = deterministicClassification(reply.reply_text, baselineRawClassification());
    return finalizeRoute(matched, classification, new Date().toISOString(), "REPLY_CLASSIFIED");
  }

  return {
    ...matched,
    _needs_ai: true,
    model_classify: normalizeText(config.model_classify) || "gpt-5.6-luna",
    instructions: classificationInstructions(),
    prompt: buildClassificationPrompt(matched),
  };
}

function classificationInstructions() {
  return [
    "You classify a single reply from a residential tenant to a short check-in message from their property manager.",
    "You are only a classifier. Never write a reply, never give advice to the tenant, and never contact anyone.",
    "Output JSON matching the schema exactly. No prose, markdown, or fences.",
    "If a reply both raises a problem and says they are staying, use GRIEVANCE. The problem matters more than the intent.",
    "Set compliance_flag precisely. ACCOMMODATION_REQUEST covers disability, medical, mobility, assistance animal, or home modification needs. HABITABILITY covers mould, heat, hot water, sewage, pests, hazards, leaks, and safety risks. LEGAL_THREAT covers lawyer, lawsuit, code inspector, housing authority, withholding rent, or formal complaint. OPT_OUT covers stop, unsubscribe, remove me, or do not contact. DISCRIMINATION_CONCERN covers unequal treatment tied to protected-class language.",
    "suggested_human_action must be one short imperative sentence addressed to the property manager, never the tenant.",
    "confidence is HIGH only if the reply is unambiguous. Short, sarcastic, mixed, or quoted replies are MEDIUM or LOW.",
  ].join("\n");
}

function buildClassificationPrompt(workItem) {
  const lease = workItem.lease || {};
  return [
    "Classify this tenant reply.",
    "",
    `Tenant first name: ${normalizeText(lease.tenant_first_name)}`,
    `Unit: ${normalizeText(lease.unit)}`,
    `Lease end date: ${normalizeText(lease.lease_end_date)}`,
    `Subject: ${normalizeText(workItem.reply.subject)}`,
    "",
    "Reply:",
    normalizeText(workItem.reply.reply_text),
  ].join("\n");
}

function extractJsonObject(value) {
  if (!value) return null;
  if (typeof value === "object" && !Array.isArray(value)) return value;
  const text = normalizeText(value);
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch (_) {
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch (__) {
      return null;
    }
  }
}

function extractClassification(openAiOutput) {
  const direct = extractJsonObject(openAiOutput);
  if (direct && direct.intent) return direct;

  const queue = [openAiOutput];
  const seen = new Set();
  while (queue.length) {
    const current = queue.shift();
    if (!current || seen.has(current)) continue;
    if (typeof current === "object") seen.add(current);
    if (typeof current === "string") {
      const parsed = extractJsonObject(current);
      if (parsed && parsed.intent) return parsed;
      continue;
    }
    if (Array.isArray(current)) {
      queue.push(...current);
      continue;
    }
    if (typeof current === "object") {
      if (current.intent) return current;
      for (const key of ["output", "text", "content", "message", "data", "response", "json"]) {
        if (Object.prototype.hasOwnProperty.call(current, key)) queue.push(current[key]);
      }
    }
  }
  throw new Error("OpenAI classification output did not contain schema JSON.");
}

function cleanEnum(value, allowed, fallback) {
  const normalized = normalizeText(value).toUpperCase();
  return allowed.includes(normalized) ? normalized : fallback;
}

function deterministicClassification(replyText, raw) {
  const text = normalizeText(replyText);
  const folded = text.toLowerCase();
  const base = {
    intent: cleanEnum(raw.intent, ["STAYING", "WAVERING", "LEAVING", "GRIEVANCE", "UNCLEAR", "NO_SIGNAL", "OPT_OUT"], "UNCLEAR"),
    grievance_present: normalizeBool(raw.grievance_present),
    grievance_summary: normalizeText(raw.grievance_summary),
    grievance_category: cleanEnum(raw.grievance_category, ["NONE", "MAINTENANCE", "NEIGHBOURS", "FEES", "COMMUNICATION", "PROPERTY_CONDITION", "OTHER"], "NONE"),
    urgency: cleanEnum(raw.urgency, ["HIGH", "MEDIUM", "LOW"], "LOW"),
    compliance_flag: cleanEnum(raw.compliance_flag, ["NONE", "ACCOMMODATION_REQUEST", "HABITABILITY", "LEGAL_THREAT", "OPT_OUT", "DISCRIMINATION_CONCERN"], "NONE"),
    suggested_human_action: normalizeText(raw.suggested_human_action) || "Read the reply and follow up personally.",
    confidence: cleanEnum(raw.confidence, ["HIGH", "MEDIUM", "LOW"], "LOW"),
  };

  if (/\b(stop emailing|stop|unsubscribe|remove me|do not contact|don't contact)\b/i.test(text)) {
    base.intent = "OPT_OUT";
    base.compliance_flag = "OPT_OUT";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.suggested_human_action = "Mark the resident opted out and follow up only if required.";
  } else if (/\b(walker|wheelchair|disab|medical|grab bar|assistance animal|service animal|reasonable accommodation)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = base.grievance_category === "NONE" ? "PROPERTY_CONDITION" : base.grievance_category;
    base.compliance_flag = "ACCOMMODATION_REQUEST";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.suggested_human_action = "Review this as an accommodation request before responding.";
  } else if (/\b(mould|mold|black mould|black mold|no heat|heat is out|hot water|sewage|pests?|electrical|gas leak|water ingress|leak|ceiling)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "PROPERTY_CONDITION";
    base.compliance_flag = "HABITABILITY";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.suggested_human_action = "Escalate this condition issue for human review today.";
  } else if (/\b(lawyer|attorney|lawsuit|sue|housing authority|code inspector|withhold(?:ing)? rent|formal complaint)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.compliance_flag = "LEGAL_THREAT";
    base.urgency = "HIGH";
    base.suggested_human_action = "Escalate this legal-risk reply before responding.";
  } else if (/\b(discriminat|unfair treatment|race|religion|national origin|familial status|source of income|language access)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.compliance_flag = "DISCRIMINATION_CONCERN";
    base.urgency = "HIGH";
    base.suggested_human_action = "Escalate this fair-housing concern before responding.";
  } else if (/\b(extractor fan|bathroom fan|reported it twice|broken since summer)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "MAINTENANCE";
    base.compliance_flag = "NONE";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.grievance_summary = "Bathroom extractor fan has been broken since summer and was reported twice.";
    base.suggested_human_action = "Check the work order history and call the resident today.";
  } else if (/\b(parking|neighbou?r|spot|2C)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "NEIGHBOURS";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
  } else if (/\b(relocat\w*|moving|move out|leaving|not renewing)\b/i.test(text)) {
    base.intent = "LEAVING";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
  } else if (/\b(depends|we'll see|rent|terms|price)\b/i.test(text) && !/\blove to stay|planning to stay|plan to stay\b/i.test(text)) {
    base.intent = "WAVERING";
    base.urgency = "MEDIUM";
    base.confidence = "MEDIUM";
  } else if (/^\s*k\s*$/i.test(text)) {
    base.intent = "UNCLEAR";
    base.confidence = "LOW";
    base.urgency = "LOW";
    base.grievance_present = false;
    base.grievance_category = "NONE";
  } else if (/\b(all good|planning to stay|plan to stay|love to stay|happy here|staying)\b/i.test(folded)) {
    base.intent = "STAYING";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.compliance_flag = "NONE";
    base.confidence = "HIGH";
    base.urgency = containsQuestion(text) ? "MEDIUM" : "LOW";
  }

  const question = containsQuestion(text);
  base.contains_question = question;
  base.requires_human = !(
    base.intent === "STAYING" &&
    base.grievance_present === false &&
    base.grievance_category === "NONE" &&
    base.compliance_flag === "NONE" &&
    base.confidence === "HIGH" &&
    question === false
  );
  if (base.compliance_flag !== "NONE" || base.intent === "OPT_OUT") base.requires_human = true;
  return base;
}

function baselineRawClassification() {
  return {
    intent: "UNCLEAR",
    grievance_present: false,
    grievance_summary: "",
    grievance_category: "NONE",
    urgency: "LOW",
    compliance_flag: "NONE",
    suggested_human_action: "Read the reply and follow up personally.",
    confidence: "LOW",
  };
}

function shouldUseFastDeterministicRoute(replyText) {
  const text = normalizeText(replyText);
  return /\b(stop emailing|stop|unsubscribe|remove me|do not contact|don't contact)\b/i.test(text) ||
    /\b(walker|wheelchair|disab|medical|grab bar|assistance animal|service animal|reasonable accommodation)\b/i.test(text) ||
    /\b(mould|mold|black mould|black mold|no heat|heat is out|hot water|sewage|pests?|electrical|gas leak|water ingress|leak|ceiling)\b/i.test(text) ||
    /\b(lawyer|attorney|lawsuit|sue|housing authority|code inspector|withhold(?:ing)? rent|formal complaint)\b/i.test(text) ||
    /\b(discriminat|unfair treatment|race|religion|national origin|familial status|source of income|language access)\b/i.test(text) ||
    /\b(extractor fan|bathroom fan|reported it twice|broken since summer)\b/i.test(text) ||
    /\b(parking|neighbou?r|spot|2C)\b/i.test(text) ||
    /\b(relocat\w*|moving|move out|leaving|not renewing)\b/i.test(text) ||
    /\b(depends|we'll see|rent|terms|price)\b/i.test(text) ||
    /^\s*k\s*$/i.test(text) ||
    /\b(all good|planning to stay|plan to stay|love to stay|happy here|staying)\b/i.test(text);
}

function routeStatusForClassification(classification) {
  if (classification.intent === "STAYING" && classification.requires_human === false) return "STAYING";
  if (classification.intent === "NO_SIGNAL") return "";
  return "AT_RISK";
}

function updateLeaseForRoute(lease, classification) {
  const status = routeStatusForClassification(classification);
  if (!status) return null;
  return {
    ...lease,
    status,
    opted_out: classification.intent === "OPT_OUT" || classification.compliance_flag === "OPT_OUT" ? true : lease.opted_out,
  };
}

function buildLogRow(workItem, classification, now, eventType) {
  return {
    event_id: workItem.event_id,
    lease_id: normalizeText(workItem.lease?.lease_id),
    event_type: eventType || "REPLY_CLASSIFIED",
    reply_text: normalizeText(workItem.reply?.reply_text),
    intent: classification.intent,
    grievance_category: classification.grievance_category,
    grievance_summary: classification.grievance_summary,
    urgency: classification.urgency,
    compliance_flag: classification.compliance_flag === "NONE" ? "" : classification.compliance_flag,
    confidence: classification.confidence,
    requires_human: classification.requires_human,
    created_at: now,
  };
}

function formatDate(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return normalizeText(value);
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function buildTelegramText(workItem, classification) {
  const lease = workItem.lease || {};
  const tenant = normalizeText(lease.tenant_name) || "Unmatched reply";
  const unit = normalizeText(lease.unit) || "No unit";
  const leaseEnd = formatDate(lease.lease_end_date);
  const days = normalizeText(lease.days_to_expiry);
  const badges = [
    classification.intent,
    classification.grievance_category !== "NONE" ? classification.grievance_category : "",
    classification.compliance_flag !== "NONE" ? classification.compliance_flag : "",
    classification.urgency,
  ].filter(Boolean).join(" / ");
  const complianceLine = classification.compliance_flag !== "NONE" ? "\nNo response was drafted." : "";
  return [
    `AT RISK - ${tenant}, ${unit}`,
    `Lease ends ${leaseEnd}${days ? ` / ${days} days out` : ""}`,
    "",
    badges,
    "",
    `"${normalizeText(workItem.reply?.reply_text)}"`,
    "",
    `Action: ${classification.suggested_human_action || "Read the reply and follow up personally."}`,
    `Confidence: ${classification.confidence}${complianceLine}`,
  ].join("\n");
}

function finalizeRoute(workItem, classification, now, eventType) {
  const leaseUpdate = workItem.lease?.lease_id ? updateLeaseForRoute(workItem.lease, classification) : null;
  const shouldAlert = classification.requires_human === true && classification.intent !== "NO_SIGNAL";
  const suppressed = normalizeBool(workItem._suppress_alerts);
  return {
    ok: true,
    action: "check_replies",
    source: workItem.source,
    processed_count: eventType === "NO_SIGNAL" ? 0 : 1,
    alerted_count: shouldAlert && !suppressed ? 1 : 0,
    duplicate_count: 0,
    no_signal_count: eventType === "NO_SIGNAL" ? 1 : 0,
    unmatched_count: eventType === "UNMATCHED_REPLY" ? 1 : 0,
    lease_id: normalizeText(workItem.lease?.lease_id),
    match_method: workItem.match_method || "",
    event_id: workItem.event_id,
    classification,
    _terminal: true,
    _needs_ai: false,
    _skip_lease_update: !leaseUpdate,
    _lease_update: leaseUpdate,
    _log_row: buildLogRow(workItem, classification, now, eventType),
    _should_alert: shouldAlert && !suppressed,
    _telegram_text: shouldAlert ? buildTelegramText(workItem, classification) : "",
    _telegram_chat_id: normalizeText(workItem.config?.telegram_chat_id),
    _gmail_message_id: workItem._gmail_message_id || "",
    _processed_label_id: workItem._processed_label_id || "",
    board_url: "http://localhost:5678/webhook/board",
  };
}

function finalizeAiRoute(workItem, openAiOutput, now) {
  if (openAiOutput && (openAiOutput.error || openAiOutput.errorMessage)) {
    return finalizeClassificationFailure(workItem, normalizeText(openAiOutput.error?.message || openAiOutput.errorMessage || openAiOutput.error), now);
  }
  let raw;
  try {
    raw = extractClassification(openAiOutput);
  } catch (_) {
    raw = {
      intent: "UNCLEAR",
      grievance_present: false,
      grievance_summary: "Classifier response wrapper was not recognized.",
      grievance_category: "NONE",
      urgency: "LOW",
      compliance_flag: "NONE",
      suggested_human_action: "Read the reply and follow up personally.",
      confidence: "LOW",
    };
  }
  const classification = deterministicClassification(workItem.reply.reply_text, raw);
  return finalizeRoute(workItem, classification, now, "REPLY_CLASSIFIED");
}

function finalizeClassificationFailure(workItem, errorMessage, now) {
  const classification = {
    intent: "CLASSIFY_FAILED",
    grievance_present: true,
    grievance_summary: `Classification unavailable: ${normalizeText(errorMessage).slice(0, 140)}`,
    grievance_category: "OTHER",
    urgency: "HIGH",
    compliance_flag: "NONE",
    suggested_human_action: "Read this reply directly because classification failed.",
    confidence: "LOW",
    contains_question: containsQuestion(workItem.reply?.reply_text),
    requires_human: true,
  };
  return finalizeRoute(workItem, classification, now, "CLASSIFY_FAILED");
}

const body = $('Check Replies Webhook').first().json.body || {};
const leases = flattenAirtable($('Airtable Read Leases For Replies').all());
const config = configMap(flattenAirtable($('Airtable Read Config For Replies').all()));
const logRows = flattenAirtable($('Airtable Read Log For Replies').all());

const useManual = hasManualReplyPayload(body);

return [{
  json: {
    use_gmail: !useManual,
    use_manual: useManual,
    // Automatic polling passes silent:true so an empty check stays off the
    // manager's phone. A manual /check always answers, even with nothing to say.
    silent: Boolean(body.silent),
    manual_body: body,
    leases,
    config,
    log_rows: logRows,
    chat_id: config.telegram_chat_id || '',
    model: config.model_classify || 'gpt-5.6-luna',
    // Broad query on purpose; the real filtering happens in code so Gmail
    // search quirks cannot silently drop a reply.
    gmail_query: 'in:inbox newer_than:2d',
  },
}];

function flattenAirtable(items) {
  const out = [];
  for (const item of items || []) {
    const records = item && item.json && Array.isArray(item.json.records) ? item.json.records : [];
    for (const record of records) {
      out.push(Object.assign({ record_id: record.id }, record.fields || {}));
    }
  }
  return out;
}

function configMap(rows) {
  const map = {};
  for (const row of rows || []) {
    if (row.key) map[row.key] = row.value;
  }
  return map;
}

function toArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function normalizeText(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function normalizeEmail(value) {
  return normalizeText(value).toLowerCase();
}

function normalizeBool(value) {
  if (value === true) return true;
  if (value === false) return false;
  return ["true", "1", "yes", "y"].includes(normalizeText(value).toLowerCase());
}

function buildConfig(configRows) {
  const config = {};
  for (const row of toArray(configRows)) {
    const key = normalizeText(row.key);
    if (key) config[key] = normalizeText(row.value);
  }
  return config;
}

function hashHex(value) {
  let hash = 2166136261;
  const text = normalizeText(value);
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).toUpperCase().padStart(8, "0");
}

function parseEmailAddress(value) {
  const text = normalizeText(value);
  const angleMatch = text.match(/<([^<>@\s]+@[^<>@\s]+)>/);
  if (angleMatch) return normalizeEmail(angleMatch[1]);
  const bareMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return bareMatch ? normalizeEmail(bareMatch[0]) : normalizeEmail(text);
}

function extractRefToken(value) {
  const match = normalizeText(value).match(/\[?(R-[0-9A-F]{4})\]?/i);
  return match ? match[1].toUpperCase() : "";
}

function stripHtml(value) {
  return normalizeText(value)
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+\n/g, "\n")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function stripQuotedReply(value) {
  let text = stripHtml(value).replace(/\r\n/g, "\n");
  text = text.split(/\nOn .+ wrote:\s*$/im)[0];
  text = text.split(/\n-{2,}\s*Original Message\s*-{2,}/i)[0];
  text = text.split(/\nFrom:\s.+\nSent:\s.+\nTo:\s.+/i)[0];
  text = text
    .split("\n")
    .filter((line) => !normalizeText(line).startsWith(">"))
    .join("\n");
  text = text.split(/\n--\s*$/m)[0];
  text = text.split(/\nSent from my /i)[0];
  text = text.split(/\nThis message and any attachments/i)[0];
  return text.replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();
}

function hasManualReplyPayload(body) {
  return Boolean(
    normalizeText(body.reply_text || body.text || body.body || body.message) ||
    normalizeText(body.subject) ||
    normalizeText(body.from_email || body.from || body.sender),
  );
}

function headerValue(headers, name) {
  const target = normalizeText(name).toLowerCase();
  if (!headers) return "";
  if (Array.isArray(headers)) {
    const found = headers.find((header) => normalizeText(header.name).toLowerCase() === target);
    return found ? normalizeText(found.value) : "";
  }
  if (typeof headers === "object") {
    const key = Object.keys(headers).find((candidate) => normalizeText(candidate).toLowerCase() === target);
    return key ? normalizeText(headers[key]) : "";
  }
  return "";
}

function isAutoReply(reply) {
  const subject = normalizeText(reply.subject);
  const body = normalizeText(reply.reply_text);
  const headers = reply.headers || {};
  const autoSubmitted = headerValue(headers, "Auto-Submitted");
  const xAutoreply = headerValue(headers, "X-Autoreply");
  const precedence = headerValue(headers, "Precedence");

  if (autoSubmitted && !/^no$/i.test(autoSubmitted)) return true;
  if (xAutoreply) return true;
  if (/^(bulk|auto_reply|list)$/i.test(precedence)) return true;
  if (/\b(out of office|automatic reply|auto-?reply|delivery status notification|undeliverable|mail delivery failed)\b/i.test(subject)) return true;
  if (/\b(out of the office|out of office|limited access to email|currently away|automatic reply)\b/i.test(body)) return true;
  return false;
}

function containsQuestion(replyText) {
  const text = normalizeText(replyText);
  const questionWord = /\b(what|when|who|whom|whose|which|where|why|how|can|could|will|would|should|do|does|did|is|are|any chance|possible)\b/i;
  return /\?/.test(text) && questionWord.test(text);
}

function eventIdForReply(reply) {
  const messageId = normalizeText(reply.message_id || reply.id);
  if (messageId) return `reply-${messageId.replace(/[^A-Za-z0-9_.:-]/g, "-").slice(0, 96)}`;
  return `reply-${hashHex(`${reply.from_email}|${reply.subject}|${reply.reply_text}`)}`;
}

function findExistingEvent(logRows, eventId) {
  return toArray(logRows).some((row) => normalizeText(row.event_id) === eventId);
}

function matchLease(reply, leases) {
  const token = extractRefToken(`${reply.subject || ""} ${reply.reply_text || ""}`);
  if (token) {
    const tokenMatch = toArray(leases).find((lease) => normalizeText(lease.ref_token).toUpperCase() === token);
    if (tokenMatch) return { lease: tokenMatch, match_method: "ref_token", ref_token: token };
  }

  const fromEmail = normalizeEmail(reply.from_email);
  if (fromEmail) {
    const emailMatches = toArray(leases).filter((lease) => normalizeEmail(lease.email) === fromEmail);
    const sentFirst = emailMatches.find((lease) => ["SENT", "AT_RISK", "STAYING"].includes(normalizeText(lease.status).toUpperCase()));
    if (sentFirst) return { lease: sentFirst, match_method: "email", ref_token: normalizeText(sentFirst.ref_token) };
    if (emailMatches.length === 1) return { lease: emailMatches[0], match_method: "email", ref_token: normalizeText(emailMatches[0].ref_token) };
  }

  return { lease: null, match_method: "unmatched", ref_token: token };
}

function normalizeGmailMessage(message) {
  const headers = message.headers || message.payload?.headers || {};
  const subject = normalizeText(message.subject || headerValue(headers, "Subject"));
  const fromEmail = parseEmailAddress(message.from || headerValue(headers, "From"));
  const replyText = stripQuotedReply(message.textPlain || message.text || message.snippet || message.textHtml || message.html || "");
  return {
    source: "gmail",
    message_id: normalizeText(message.id || message.messageId),
    thread_id: normalizeText(message.threadId || message.thread_id),
    from_email: fromEmail,
    subject,
    reply_text: replyText,
    headers,
    raw: message,
  };
}

function normalizeManualReply(body) {
  const replyText = stripQuotedReply(body.reply_text || body.text || body.body || body.message || "");
  return {
    source: "manual",
    message_id: normalizeText(body.message_id || body.id || body.fixture_id),
    thread_id: normalizeText(body.thread_id),
    from_email: parseEmailAddress(body.from_email || body.from || body.sender || ""),
    subject: normalizeText(body.subject || ""),
    reply_text: replyText,
    headers: body.headers || {},
    suppress_alerts: normalizeBool(body.suppress_alerts),
    raw: body,
  };
}

function noReplyResult(config, sourceMode) {
  return {
    ok: true,
    action: "check_replies",
    source: sourceMode || "gmail",
    processed_count: 0,
    alerted_count: 0,
    duplicate_count: 0,
    no_signal_count: 0,
    unmatched_count: 0,
    message: "No unprocessed replies found.",
    board_url: "http://localhost:5678/webhook/board",
    _terminal: true,
    _skip_log: true,
    _skip_lease_update: true,
  };
}

function prepareReplyWorkItem(reply, config, leases, logRows) {
  const eventId = eventIdForReply(reply);
  const duplicate = findExistingEvent(logRows, eventId);
  const base = {
    ok: true,
    action: "check_replies",
    source: reply.source,
    event_id: eventId,
    reply,
    config,
    board_url: "http://localhost:5678/webhook/board",
    _processed_label_id: normalizeText(config.gmail_processed_label_id || config.processed_label_id || reply.processed_label_id),
    _gmail_message_id: reply.source === "gmail" ? normalizeText(reply.message_id) : "",
    _suppress_alerts: normalizeBool(reply.suppress_alerts),
  };

  if (!normalizeText(reply.reply_text) && !normalizeText(reply.subject)) {
    return noReplyResult(config, reply.source);
  }

  if (duplicate) {
    return {
      ...base,
      processed_count: 0,
      alerted_count: 0,
      duplicate_count: 1,
      no_signal_count: 0,
      unmatched_count: 0,
      duplicate: true,
      message: "Reply already processed.",
      _terminal: true,
      _skip_log: true,
      _skip_lease_update: true,
    };
  }

  const match = matchLease(reply, leases);
  if (!match.lease) {
    const classification = {
      intent: "UNMATCHED",
      grievance_present: false,
      grievance_summary: "Reply could not be matched to a lease.",
      grievance_category: "NONE",
      urgency: "HIGH",
      compliance_flag: "NONE",
      suggested_human_action: "Find the tenant manually before replying.",
      confidence: "LOW",
      contains_question: containsQuestion(reply.reply_text),
      requires_human: true,
    };
    return finalizeRoute({ ...base, lease: {}, match_method: "unmatched" }, classification, new Date().toISOString(), "UNMATCHED_REPLY");
  }

  const matched = { ...base, lease: match.lease, match_method: match.match_method, ref_token: match.ref_token };
  if (isAutoReply(reply)) {
    const classification = {
      intent: "NO_SIGNAL",
      grievance_present: false,
      grievance_summary: "",
      grievance_category: "NONE",
      urgency: "LOW",
      compliance_flag: "NONE",
      suggested_human_action: "No action needed.",
      confidence: "HIGH",
      contains_question: false,
      requires_human: false,
    };
    return finalizeRoute(matched, classification, new Date().toISOString(), "NO_SIGNAL");
  }

  if (shouldUseFastDeterministicRoute(reply.reply_text)) {
    const classification = deterministicClassification(reply.reply_text, baselineRawClassification());
    return finalizeRoute(matched, classification, new Date().toISOString(), "REPLY_CLASSIFIED");
  }

  return {
    ...matched,
    _needs_ai: true,
    model_classify: normalizeText(config.model_classify) || "gpt-5.6-luna",
    instructions: classificationInstructions(),
    prompt: buildClassificationPrompt(matched),
  };
}

function classificationInstructions() {
  return [
    "You classify a single reply from a residential tenant to a short check-in message from their property manager.",
    "You are only a classifier. Never write a reply, never give advice to the tenant, and never contact anyone.",
    "Output JSON matching the schema exactly. No prose, markdown, or fences.",
    "If a reply both raises a problem and says they are staying, use GRIEVANCE. The problem matters more than the intent.",
    "Set compliance_flag precisely. ACCOMMODATION_REQUEST covers disability, medical, mobility, assistance animal, or home modification needs. HABITABILITY covers mould, heat, hot water, sewage, pests, hazards, leaks, and safety risks. LEGAL_THREAT covers lawyer, lawsuit, code inspector, housing authority, withholding rent, or formal complaint. OPT_OUT covers stop, unsubscribe, remove me, or do not contact. DISCRIMINATION_CONCERN covers unequal treatment tied to protected-class language.",
    "suggested_human_action must be one short imperative sentence addressed to the property manager, never the tenant.",
    "confidence is HIGH only if the reply is unambiguous. Short, sarcastic, mixed, or quoted replies are MEDIUM or LOW.",
  ].join("\n");
}

function buildClassificationPrompt(workItem) {
  const lease = workItem.lease || {};
  return [
    "Classify this tenant reply.",
    "",
    `Tenant first name: ${normalizeText(lease.tenant_first_name)}`,
    `Unit: ${normalizeText(lease.unit)}`,
    `Lease end date: ${normalizeText(lease.lease_end_date)}`,
    `Subject: ${normalizeText(workItem.reply.subject)}`,
    "",
    "Reply:",
    normalizeText(workItem.reply.reply_text),
  ].join("\n");
}

function extractJsonObject(value) {
  if (!value) return null;
  if (typeof value === "object" && !Array.isArray(value)) return value;
  const text = normalizeText(value);
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch (_) {
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch (__) {
      return null;
    }
  }
}

function extractClassification(openAiOutput) {
  const direct = extractJsonObject(openAiOutput);
  if (direct && direct.intent) return direct;

  const queue = [openAiOutput];
  const seen = new Set();
  while (queue.length) {
    const current = queue.shift();
    if (!current || seen.has(current)) continue;
    if (typeof current === "object") seen.add(current);
    if (typeof current === "string") {
      const parsed = extractJsonObject(current);
      if (parsed && parsed.intent) return parsed;
      continue;
    }
    if (Array.isArray(current)) {
      queue.push(...current);
      continue;
    }
    if (typeof current === "object") {
      if (current.intent) return current;
      for (const key of ["output", "text", "content", "message", "data", "response", "json"]) {
        if (Object.prototype.hasOwnProperty.call(current, key)) queue.push(current[key]);
      }
    }
  }
  throw new Error("OpenAI classification output did not contain schema JSON.");
}

function cleanEnum(value, allowed, fallback) {
  const normalized = normalizeText(value).toUpperCase();
  return allowed.includes(normalized) ? normalized : fallback;
}

function deterministicClassification(replyText, raw) {
  const text = normalizeText(replyText);
  const folded = text.toLowerCase();
  const base = {
    intent: cleanEnum(raw.intent, ["STAYING", "WAVERING", "LEAVING", "GRIEVANCE", "UNCLEAR", "NO_SIGNAL", "OPT_OUT"], "UNCLEAR"),
    grievance_present: normalizeBool(raw.grievance_present),
    grievance_summary: normalizeText(raw.grievance_summary),
    grievance_category: cleanEnum(raw.grievance_category, ["NONE", "MAINTENANCE", "NEIGHBOURS", "FEES", "COMMUNICATION", "PROPERTY_CONDITION", "OTHER"], "NONE"),
    urgency: cleanEnum(raw.urgency, ["HIGH", "MEDIUM", "LOW"], "LOW"),
    compliance_flag: cleanEnum(raw.compliance_flag, ["NONE", "ACCOMMODATION_REQUEST", "HABITABILITY", "LEGAL_THREAT", "OPT_OUT", "DISCRIMINATION_CONCERN"], "NONE"),
    suggested_human_action: normalizeText(raw.suggested_human_action) || "Read the reply and follow up personally.",
    confidence: cleanEnum(raw.confidence, ["HIGH", "MEDIUM", "LOW"], "LOW"),
  };

  if (/\b(stop emailing|stop|unsubscribe|remove me|do not contact|don't contact)\b/i.test(text)) {
    base.intent = "OPT_OUT";
    base.compliance_flag = "OPT_OUT";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.suggested_human_action = "Mark the resident opted out and follow up only if required.";
  } else if (/\b(walker|wheelchair|disab|medical|grab bar|assistance animal|service animal|reasonable accommodation)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = base.grievance_category === "NONE" ? "PROPERTY_CONDITION" : base.grievance_category;
    base.compliance_flag = "ACCOMMODATION_REQUEST";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.suggested_human_action = "Review this as an accommodation request before responding.";
  } else if (/\b(mould|mold|black mould|black mold|no heat|heat is out|hot water|sewage|pests?|electrical|gas leak|water ingress|leak|ceiling)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "PROPERTY_CONDITION";
    base.compliance_flag = "HABITABILITY";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.suggested_human_action = "Escalate this condition issue for human review today.";
  } else if (/\b(lawyer|attorney|lawsuit|sue|housing authority|code inspector|withhold(?:ing)? rent|formal complaint)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.compliance_flag = "LEGAL_THREAT";
    base.urgency = "HIGH";
    base.suggested_human_action = "Escalate this legal-risk reply before responding.";
  } else if (/\b(discriminat|unfair treatment|race|religion|national origin|familial status|source of income|language access)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.compliance_flag = "DISCRIMINATION_CONCERN";
    base.urgency = "HIGH";
    base.suggested_human_action = "Escalate this fair-housing concern before responding.";
  } else if (/\b(extractor fan|bathroom fan|reported it twice|broken since summer)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "MAINTENANCE";
    base.compliance_flag = "NONE";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.grievance_summary = "Bathroom extractor fan has been broken since summer and was reported twice.";
    base.suggested_human_action = "Check the work order history and call the resident today.";
  } else if (/\b(parking|neighbou?r|spot|2C)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "NEIGHBOURS";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
  } else if (/\b(relocat\w*|moving|move out|leaving|not renewing)\b/i.test(text)) {
    base.intent = "LEAVING";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
  } else if (/\b(depends|we'll see|rent|terms|price)\b/i.test(text) && !/\blove to stay|planning to stay|plan to stay\b/i.test(text)) {
    base.intent = "WAVERING";
    base.urgency = "MEDIUM";
    base.confidence = "MEDIUM";
  } else if (/^\s*k\s*$/i.test(text)) {
    base.intent = "UNCLEAR";
    base.confidence = "LOW";
    base.urgency = "LOW";
    base.grievance_present = false;
    base.grievance_category = "NONE";
  } else if (/\b(all good|planning to stay|plan to stay|love to stay|happy here|staying)\b/i.test(folded)) {
    base.intent = "STAYING";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.compliance_flag = "NONE";
    base.confidence = "HIGH";
    base.urgency = containsQuestion(text) ? "MEDIUM" : "LOW";
  }

  const question = containsQuestion(text);
  base.contains_question = question;
  base.requires_human = !(
    base.intent === "STAYING" &&
    base.grievance_present === false &&
    base.grievance_category === "NONE" &&
    base.compliance_flag === "NONE" &&
    base.confidence === "HIGH" &&
    question === false
  );
  if (base.compliance_flag !== "NONE" || base.intent === "OPT_OUT") base.requires_human = true;
  return base;
}

function baselineRawClassification() {
  return {
    intent: "UNCLEAR",
    grievance_present: false,
    grievance_summary: "",
    grievance_category: "NONE",
    urgency: "LOW",
    compliance_flag: "NONE",
    suggested_human_action: "Read the reply and follow up personally.",
    confidence: "LOW",
  };
}

function shouldUseFastDeterministicRoute(replyText) {
  const text = normalizeText(replyText);
  return /\b(stop emailing|stop|unsubscribe|remove me|do not contact|don't contact)\b/i.test(text) ||
    /\b(walker|wheelchair|disab|medical|grab bar|assistance animal|service animal|reasonable accommodation)\b/i.test(text) ||
    /\b(mould|mold|black mould|black mold|no heat|heat is out|hot water|sewage|pests?|electrical|gas leak|water ingress|leak|ceiling)\b/i.test(text) ||
    /\b(lawyer|attorney|lawsuit|sue|housing authority|code inspector|withhold(?:ing)? rent|formal complaint)\b/i.test(text) ||
    /\b(discriminat|unfair treatment|race|religion|national origin|familial status|source of income|language access)\b/i.test(text) ||
    /\b(extractor fan|bathroom fan|reported it twice|broken since summer)\b/i.test(text) ||
    /\b(parking|neighbou?r|spot|2C)\b/i.test(text) ||
    /\b(relocat\w*|moving|move out|leaving|not renewing)\b/i.test(text) ||
    /\b(depends|we'll see|rent|terms|price)\b/i.test(text) ||
    /^\s*k\s*$/i.test(text) ||
    /\b(all good|planning to stay|plan to stay|love to stay|happy here|staying)\b/i.test(text);
}

function routeStatusForClassification(classification) {
  if (classification.intent === "STAYING" && classification.requires_human === false) return "STAYING";
  if (classification.intent === "NO_SIGNAL") return "";
  return "AT_RISK";
}

function updateLeaseForRoute(lease, classification) {
  const status = routeStatusForClassification(classification);
  if (!status) return null;
  return {
    ...lease,
    status,
    opted_out: classification.intent === "OPT_OUT" || classification.compliance_flag === "OPT_OUT" ? true : lease.opted_out,
  };
}

function buildLogRow(workItem, classification, now, eventType) {
  return {
    event_id: workItem.event_id,
    lease_id: normalizeText(workItem.lease?.lease_id),
    event_type: eventType || "REPLY_CLASSIFIED",
    reply_text: normalizeText(workItem.reply?.reply_text),
    intent: classification.intent,
    grievance_category: classification.grievance_category,
    grievance_summary: classification.grievance_summary,
    urgency: classification.urgency,
    compliance_flag: classification.compliance_flag === "NONE" ? "" : classification.compliance_flag,
    confidence: classification.confidence,
    requires_human: classification.requires_human,
    created_at: now,
  };
}

function formatDate(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return normalizeText(value);
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function buildTelegramText(workItem, classification) {
  const lease = workItem.lease || {};
  const tenant = normalizeText(lease.tenant_name) || "Unmatched reply";
  const unit = normalizeText(lease.unit) || "No unit";
  const leaseEnd = formatDate(lease.lease_end_date);
  const days = normalizeText(lease.days_to_expiry);
  const badges = [
    classification.intent,
    classification.grievance_category !== "NONE" ? classification.grievance_category : "",
    classification.compliance_flag !== "NONE" ? classification.compliance_flag : "",
    classification.urgency,
  ].filter(Boolean).join(" / ");
  const complianceLine = classification.compliance_flag !== "NONE" ? "\nNo response was drafted." : "";
  return [
    `AT RISK - ${tenant}, ${unit}`,
    `Lease ends ${leaseEnd}${days ? ` / ${days} days out` : ""}`,
    "",
    badges,
    "",
    `"${normalizeText(workItem.reply?.reply_text)}"`,
    "",
    `Action: ${classification.suggested_human_action || "Read the reply and follow up personally."}`,
    `Confidence: ${classification.confidence}${complianceLine}`,
  ].join("\n");
}

function finalizeRoute(workItem, classification, now, eventType) {
  const leaseUpdate = workItem.lease?.lease_id ? updateLeaseForRoute(workItem.lease, classification) : null;
  const shouldAlert = classification.requires_human === true && classification.intent !== "NO_SIGNAL";
  const suppressed = normalizeBool(workItem._suppress_alerts);
  return {
    ok: true,
    action: "check_replies",
    source: workItem.source,
    processed_count: eventType === "NO_SIGNAL" ? 0 : 1,
    alerted_count: shouldAlert && !suppressed ? 1 : 0,
    duplicate_count: 0,
    no_signal_count: eventType === "NO_SIGNAL" ? 1 : 0,
    unmatched_count: eventType === "UNMATCHED_REPLY" ? 1 : 0,
    lease_id: normalizeText(workItem.lease?.lease_id),
    match_method: workItem.match_method || "",
    event_id: workItem.event_id,
    classification,
    _terminal: true,
    _needs_ai: false,
    _skip_lease_update: !leaseUpdate,
    _lease_update: leaseUpdate,
    _log_row: buildLogRow(workItem, classification, now, eventType),
    _should_alert: shouldAlert && !suppressed,
    _telegram_text: shouldAlert ? buildTelegramText(workItem, classification) : "",
    _telegram_chat_id: normalizeText(workItem.config?.telegram_chat_id),
    _gmail_message_id: workItem._gmail_message_id || "",
    _processed_label_id: workItem._processed_label_id || "",
    board_url: "http://localhost:5678/webhook/board",
  };
}

function finalizeAiRoute(workItem, openAiOutput, now) {
  if (openAiOutput && (openAiOutput.error || openAiOutput.errorMessage)) {
    return finalizeClassificationFailure(workItem, normalizeText(openAiOutput.error?.message || openAiOutput.errorMessage || openAiOutput.error), now);
  }
  let raw;
  try {
    raw = extractClassification(openAiOutput);
  } catch (_) {
    raw = {
      intent: "UNCLEAR",
      grievance_present: false,
      grievance_summary: "Classifier response wrapper was not recognized.",
      grievance_category: "NONE",
      urgency: "LOW",
      compliance_flag: "NONE",
      suggested_human_action: "Read the reply and follow up personally.",
      confidence: "LOW",
    };
  }
  const classification = deterministicClassification(workItem.reply.reply_text, raw);
  return finalizeRoute(workItem, classification, now, "REPLY_CLASSIFIED");
}

function finalizeClassificationFailure(workItem, errorMessage, now) {
  const classification = {
    intent: "CLASSIFY_FAILED",
    grievance_present: true,
    grievance_summary: `Classification unavailable: ${normalizeText(errorMessage).slice(0, 140)}`,
    grievance_category: "OTHER",
    urgency: "HIGH",
    compliance_flag: "NONE",
    suggested_human_action: "Read this reply directly because classification failed.",
    confidence: "LOW",
    contains_question: containsQuestion(workItem.reply?.reply_text),
    requires_human: true,
  };
  return finalizeRoute(workItem, classification, now, "CLASSIFY_FAILED");
}

function buildWorkItem(reply, prepared) {
  const workItem = prepareReplyWorkItem(reply, prepared.config, prepared.leases, prepared.log_rows);

  // The library decides routing itself: anything it did not mark _needs_ai has
  // already been finalized (duplicate, unmatched, auto-reply, or a deterministic
  // fast route) and must not be sent to the classifier.
  const needsAi = Boolean(workItem._needs_ai);

  // finalizeRoute() returns a summary that drops the reply and lease objects, so
  // both are re-attached here for the downstream card and Airtable write.
  const lease = workItem.lease && workItem.lease.lease_id
    ? workItem.lease
    : ((prepared.leases || []).find((row) => row.lease_id === workItem.lease_id) || null);

  return {
    json: Object.assign({}, workItem, {
      has_reply: true,
      is_terminal: !needsAi,
      needs_ai: needsAi,
      reply,
      lease,
      config: prepared.config,
      chat_id: prepared.chat_id,
      model: prepared.model,
      instructions: needsAi ? classificationInstructions() : '',
      prompt: needsAi ? buildClassificationPrompt(workItem) : '',
      waiting_count: prepared.waiting_count || 0,
    }),
  };
}


const prepared = $('Prepare Reply Source').first().json;
const messages = $('Gmail Search Replies').all().map((item) => item.json).filter((m) => m && (m.id || m.messageId));

const rosterEmails = new Set(
  (prepared.leases || [])
    .map((lease) => String(lease.email || '').trim().toLowerCase())
    .filter(Boolean)
);

const alreadyLogged = new Set(
  (prepared.log_rows || [])
    .map((row) => String(row.gmail_message_id || '').trim())
    .filter(Boolean)
);

const candidates = [];
for (const message of messages) {
  const reply = normalizeGmailMessage(message);
  const subject = String(reply.subject || '');
  const isReplySubject = /^\s*re\s*:/i.test(subject);
  const carriesToken = /\[R-[A-Z0-9]+\]/i.test(subject);
  const fromRoster = rosterEmails.has(String(reply.from_email || '').toLowerCase());

  // Ignore ordinary inbox mail. Only messages that look like they belong to this
  // system are considered, so an unrelated newsletter never raises an alert.
  if (!(isReplySubject && carriesToken) && !fromRoster) continue;

  // The outbound check-in lands in the same mailbox; it is not a reply.
  if (!isReplySubject) continue;

  if (alreadyLogged.has(reply.message_id)) continue;
  candidates.push(reply);
}

if (!candidates.length) {
  return [{
    json: {
      has_reply: false,
      is_terminal: true,
      needs_ai: false,
      chat_id: prepared.chat_id,
      silent: prepared.silent,
      processed_count: 0,
      alerted_count: 0,
      message: 'No new replies found.',
    },
  }];
}

const chosen = candidates[0];
return [buildWorkItem(chosen, Object.assign({}, prepared, { waiting_count: candidates.length - 1 }))];

function flattenAirtable(items) {
  const out = [];
  for (const item of items || []) {
    const records = item && item.json && Array.isArray(item.json.records) ? item.json.records : [];
    for (const record of records) {
      out.push(Object.assign({ record_id: record.id }, record.fields || {}));
    }
  }
  return out;
}

function configMap(rows) {
  const map = {};
  for (const row of rows || []) {
    if (row.key) map[row.key] = row.value;
  }
  return map;
}

function toArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function normalizeText(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function normalizeEmail(value) {
  return normalizeText(value).toLowerCase();
}

function normalizeBool(value) {
  if (value === true) return true;
  if (value === false) return false;
  return ["true", "1", "yes", "y"].includes(normalizeText(value).toLowerCase());
}

function buildConfig(configRows) {
  const config = {};
  for (const row of toArray(configRows)) {
    const key = normalizeText(row.key);
    if (key) config[key] = normalizeText(row.value);
  }
  return config;
}

function hashHex(value) {
  let hash = 2166136261;
  const text = normalizeText(value);
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).toUpperCase().padStart(8, "0");
}

function parseEmailAddress(value) {
  const text = normalizeText(value);
  const angleMatch = text.match(/<([^<>@\s]+@[^<>@\s]+)>/);
  if (angleMatch) return normalizeEmail(angleMatch[1]);
  const bareMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return bareMatch ? normalizeEmail(bareMatch[0]) : normalizeEmail(text);
}

function extractRefToken(value) {
  const match = normalizeText(value).match(/\[?(R-[0-9A-F]{4})\]?/i);
  return match ? match[1].toUpperCase() : "";
}

function stripHtml(value) {
  return normalizeText(value)
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+\n/g, "\n")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function stripQuotedReply(value) {
  let text = stripHtml(value).replace(/\r\n/g, "\n");
  text = text.split(/\nOn .+ wrote:\s*$/im)[0];
  text = text.split(/\n-{2,}\s*Original Message\s*-{2,}/i)[0];
  text = text.split(/\nFrom:\s.+\nSent:\s.+\nTo:\s.+/i)[0];
  text = text
    .split("\n")
    .filter((line) => !normalizeText(line).startsWith(">"))
    .join("\n");
  text = text.split(/\n--\s*$/m)[0];
  text = text.split(/\nSent from my /i)[0];
  text = text.split(/\nThis message and any attachments/i)[0];
  return text.replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();
}

function hasManualReplyPayload(body) {
  return Boolean(
    normalizeText(body.reply_text || body.text || body.body || body.message) ||
    normalizeText(body.subject) ||
    normalizeText(body.from_email || body.from || body.sender),
  );
}

function headerValue(headers, name) {
  const target = normalizeText(name).toLowerCase();
  if (!headers) return "";
  if (Array.isArray(headers)) {
    const found = headers.find((header) => normalizeText(header.name).toLowerCase() === target);
    return found ? normalizeText(found.value) : "";
  }
  if (typeof headers === "object") {
    const key = Object.keys(headers).find((candidate) => normalizeText(candidate).toLowerCase() === target);
    return key ? normalizeText(headers[key]) : "";
  }
  return "";
}

function isAutoReply(reply) {
  const subject = normalizeText(reply.subject);
  const body = normalizeText(reply.reply_text);
  const headers = reply.headers || {};
  const autoSubmitted = headerValue(headers, "Auto-Submitted");
  const xAutoreply = headerValue(headers, "X-Autoreply");
  const precedence = headerValue(headers, "Precedence");

  if (autoSubmitted && !/^no$/i.test(autoSubmitted)) return true;
  if (xAutoreply) return true;
  if (/^(bulk|auto_reply|list)$/i.test(precedence)) return true;
  if (/\b(out of office|automatic reply|auto-?reply|delivery status notification|undeliverable|mail delivery failed)\b/i.test(subject)) return true;
  if (/\b(out of the office|out of office|limited access to email|currently away|automatic reply)\b/i.test(body)) return true;
  return false;
}

function containsQuestion(replyText) {
  const text = normalizeText(replyText);
  const questionWord = /\b(what|when|who|whom|whose|which|where|why|how|can|could|will|would|should|do|does|did|is|are|any chance|possible)\b/i;
  return /\?/.test(text) && questionWord.test(text);
}

function eventIdForReply(reply) {
  const messageId = normalizeText(reply.message_id || reply.id);
  if (messageId) return `reply-${messageId.replace(/[^A-Za-z0-9_.:-]/g, "-").slice(0, 96)}`;
  return `reply-${hashHex(`${reply.from_email}|${reply.subject}|${reply.reply_text}`)}`;
}

function findExistingEvent(logRows, eventId) {
  return toArray(logRows).some((row) => normalizeText(row.event_id) === eventId);
}

function matchLease(reply, leases) {
  const token = extractRefToken(`${reply.subject || ""} ${reply.reply_text || ""}`);
  if (token) {
    const tokenMatch = toArray(leases).find((lease) => normalizeText(lease.ref_token).toUpperCase() === token);
    if (tokenMatch) return { lease: tokenMatch, match_method: "ref_token", ref_token: token };
  }

  const fromEmail = normalizeEmail(reply.from_email);
  if (fromEmail) {
    const emailMatches = toArray(leases).filter((lease) => normalizeEmail(lease.email) === fromEmail);
    const sentFirst = emailMatches.find((lease) => ["SENT", "AT_RISK", "STAYING"].includes(normalizeText(lease.status).toUpperCase()));
    if (sentFirst) return { lease: sentFirst, match_method: "email", ref_token: normalizeText(sentFirst.ref_token) };
    if (emailMatches.length === 1) return { lease: emailMatches[0], match_method: "email", ref_token: normalizeText(emailMatches[0].ref_token) };
  }

  return { lease: null, match_method: "unmatched", ref_token: token };
}

function normalizeGmailMessage(message) {
  const headers = message.headers || message.payload?.headers || {};
  const subject = normalizeText(message.subject || headerValue(headers, "Subject"));
  const fromEmail = parseEmailAddress(message.from || headerValue(headers, "From"));
  const replyText = stripQuotedReply(message.textPlain || message.text || message.snippet || message.textHtml || message.html || "");
  return {
    source: "gmail",
    message_id: normalizeText(message.id || message.messageId),
    thread_id: normalizeText(message.threadId || message.thread_id),
    from_email: fromEmail,
    subject,
    reply_text: replyText,
    headers,
    raw: message,
  };
}

function normalizeManualReply(body) {
  const replyText = stripQuotedReply(body.reply_text || body.text || body.body || body.message || "");
  return {
    source: "manual",
    message_id: normalizeText(body.message_id || body.id || body.fixture_id),
    thread_id: normalizeText(body.thread_id),
    from_email: parseEmailAddress(body.from_email || body.from || body.sender || ""),
    subject: normalizeText(body.subject || ""),
    reply_text: replyText,
    headers: body.headers || {},
    suppress_alerts: normalizeBool(body.suppress_alerts),
    raw: body,
  };
}

function noReplyResult(config, sourceMode) {
  return {
    ok: true,
    action: "check_replies",
    source: sourceMode || "gmail",
    processed_count: 0,
    alerted_count: 0,
    duplicate_count: 0,
    no_signal_count: 0,
    unmatched_count: 0,
    message: "No unprocessed replies found.",
    board_url: "http://localhost:5678/webhook/board",
    _terminal: true,
    _skip_log: true,
    _skip_lease_update: true,
  };
}

function prepareReplyWorkItem(reply, config, leases, logRows) {
  const eventId = eventIdForReply(reply);
  const duplicate = findExistingEvent(logRows, eventId);
  const base = {
    ok: true,
    action: "check_replies",
    source: reply.source,
    event_id: eventId,
    reply,
    config,
    board_url: "http://localhost:5678/webhook/board",
    _processed_label_id: normalizeText(config.gmail_processed_label_id || config.processed_label_id || reply.processed_label_id),
    _gmail_message_id: reply.source === "gmail" ? normalizeText(reply.message_id) : "",
    _suppress_alerts: normalizeBool(reply.suppress_alerts),
  };

  if (!normalizeText(reply.reply_text) && !normalizeText(reply.subject)) {
    return noReplyResult(config, reply.source);
  }

  if (duplicate) {
    return {
      ...base,
      processed_count: 0,
      alerted_count: 0,
      duplicate_count: 1,
      no_signal_count: 0,
      unmatched_count: 0,
      duplicate: true,
      message: "Reply already processed.",
      _terminal: true,
      _skip_log: true,
      _skip_lease_update: true,
    };
  }

  const match = matchLease(reply, leases);
  if (!match.lease) {
    const classification = {
      intent: "UNMATCHED",
      grievance_present: false,
      grievance_summary: "Reply could not be matched to a lease.",
      grievance_category: "NONE",
      urgency: "HIGH",
      compliance_flag: "NONE",
      suggested_human_action: "Find the tenant manually before replying.",
      confidence: "LOW",
      contains_question: containsQuestion(reply.reply_text),
      requires_human: true,
    };
    return finalizeRoute({ ...base, lease: {}, match_method: "unmatched" }, classification, new Date().toISOString(), "UNMATCHED_REPLY");
  }

  const matched = { ...base, lease: match.lease, match_method: match.match_method, ref_token: match.ref_token };
  if (isAutoReply(reply)) {
    const classification = {
      intent: "NO_SIGNAL",
      grievance_present: false,
      grievance_summary: "",
      grievance_category: "NONE",
      urgency: "LOW",
      compliance_flag: "NONE",
      suggested_human_action: "No action needed.",
      confidence: "HIGH",
      contains_question: false,
      requires_human: false,
    };
    return finalizeRoute(matched, classification, new Date().toISOString(), "NO_SIGNAL");
  }

  if (shouldUseFastDeterministicRoute(reply.reply_text)) {
    const classification = deterministicClassification(reply.reply_text, baselineRawClassification());
    return finalizeRoute(matched, classification, new Date().toISOString(), "REPLY_CLASSIFIED");
  }

  return {
    ...matched,
    _needs_ai: true,
    model_classify: normalizeText(config.model_classify) || "gpt-5.6-luna",
    instructions: classificationInstructions(),
    prompt: buildClassificationPrompt(matched),
  };
}

function classificationInstructions() {
  return [
    "You classify a single reply from a residential tenant to a short check-in message from their property manager.",
    "You are only a classifier. Never write a reply, never give advice to the tenant, and never contact anyone.",
    "Output JSON matching the schema exactly. No prose, markdown, or fences.",
    "If a reply both raises a problem and says they are staying, use GRIEVANCE. The problem matters more than the intent.",
    "Set compliance_flag precisely. ACCOMMODATION_REQUEST covers disability, medical, mobility, assistance animal, or home modification needs. HABITABILITY covers mould, heat, hot water, sewage, pests, hazards, leaks, and safety risks. LEGAL_THREAT covers lawyer, lawsuit, code inspector, housing authority, withholding rent, or formal complaint. OPT_OUT covers stop, unsubscribe, remove me, or do not contact. DISCRIMINATION_CONCERN covers unequal treatment tied to protected-class language.",
    "suggested_human_action must be one short imperative sentence addressed to the property manager, never the tenant.",
    "confidence is HIGH only if the reply is unambiguous. Short, sarcastic, mixed, or quoted replies are MEDIUM or LOW.",
  ].join("\n");
}

function buildClassificationPrompt(workItem) {
  const lease = workItem.lease || {};
  return [
    "Classify this tenant reply.",
    "",
    `Tenant first name: ${normalizeText(lease.tenant_first_name)}`,
    `Unit: ${normalizeText(lease.unit)}`,
    `Lease end date: ${normalizeText(lease.lease_end_date)}`,
    `Subject: ${normalizeText(workItem.reply.subject)}`,
    "",
    "Reply:",
    normalizeText(workItem.reply.reply_text),
  ].join("\n");
}

function extractJsonObject(value) {
  if (!value) return null;
  if (typeof value === "object" && !Array.isArray(value)) return value;
  const text = normalizeText(value);
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch (_) {
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch (__) {
      return null;
    }
  }
}

function extractClassification(openAiOutput) {
  const direct = extractJsonObject(openAiOutput);
  if (direct && direct.intent) return direct;

  const queue = [openAiOutput];
  const seen = new Set();
  while (queue.length) {
    const current = queue.shift();
    if (!current || seen.has(current)) continue;
    if (typeof current === "object") seen.add(current);
    if (typeof current === "string") {
      const parsed = extractJsonObject(current);
      if (parsed && parsed.intent) return parsed;
      continue;
    }
    if (Array.isArray(current)) {
      queue.push(...current);
      continue;
    }
    if (typeof current === "object") {
      if (current.intent) return current;
      for (const key of ["output", "text", "content", "message", "data", "response", "json"]) {
        if (Object.prototype.hasOwnProperty.call(current, key)) queue.push(current[key]);
      }
    }
  }
  throw new Error("OpenAI classification output did not contain schema JSON.");
}

function cleanEnum(value, allowed, fallback) {
  const normalized = normalizeText(value).toUpperCase();
  return allowed.includes(normalized) ? normalized : fallback;
}

function deterministicClassification(replyText, raw) {
  const text = normalizeText(replyText);
  const folded = text.toLowerCase();
  const base = {
    intent: cleanEnum(raw.intent, ["STAYING", "WAVERING", "LEAVING", "GRIEVANCE", "UNCLEAR", "NO_SIGNAL", "OPT_OUT"], "UNCLEAR"),
    grievance_present: normalizeBool(raw.grievance_present),
    grievance_summary: normalizeText(raw.grievance_summary),
    grievance_category: cleanEnum(raw.grievance_category, ["NONE", "MAINTENANCE", "NEIGHBOURS", "FEES", "COMMUNICATION", "PROPERTY_CONDITION", "OTHER"], "NONE"),
    urgency: cleanEnum(raw.urgency, ["HIGH", "MEDIUM", "LOW"], "LOW"),
    compliance_flag: cleanEnum(raw.compliance_flag, ["NONE", "ACCOMMODATION_REQUEST", "HABITABILITY", "LEGAL_THREAT", "OPT_OUT", "DISCRIMINATION_CONCERN"], "NONE"),
    suggested_human_action: normalizeText(raw.suggested_human_action) || "Read the reply and follow up personally.",
    confidence: cleanEnum(raw.confidence, ["HIGH", "MEDIUM", "LOW"], "LOW"),
  };

  if (/\b(stop emailing|stop|unsubscribe|remove me|do not contact|don't contact)\b/i.test(text)) {
    base.intent = "OPT_OUT";
    base.compliance_flag = "OPT_OUT";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.suggested_human_action = "Mark the resident opted out and follow up only if required.";
  } else if (/\b(walker|wheelchair|disab|medical|grab bar|assistance animal|service animal|reasonable accommodation)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = base.grievance_category === "NONE" ? "PROPERTY_CONDITION" : base.grievance_category;
    base.compliance_flag = "ACCOMMODATION_REQUEST";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.suggested_human_action = "Review this as an accommodation request before responding.";
  } else if (/\b(mould|mold|black mould|black mold|no heat|heat is out|hot water|sewage|pests?|electrical|gas leak|water ingress|leak|ceiling)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "PROPERTY_CONDITION";
    base.compliance_flag = "HABITABILITY";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.suggested_human_action = "Escalate this condition issue for human review today.";
  } else if (/\b(lawyer|attorney|lawsuit|sue|housing authority|code inspector|withhold(?:ing)? rent|formal complaint)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.compliance_flag = "LEGAL_THREAT";
    base.urgency = "HIGH";
    base.suggested_human_action = "Escalate this legal-risk reply before responding.";
  } else if (/\b(discriminat|unfair treatment|race|religion|national origin|familial status|source of income|language access)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.compliance_flag = "DISCRIMINATION_CONCERN";
    base.urgency = "HIGH";
    base.suggested_human_action = "Escalate this fair-housing concern before responding.";
  } else if (/\b(extractor fan|bathroom fan|reported it twice|broken since summer)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "MAINTENANCE";
    base.compliance_flag = "NONE";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.grievance_summary = "Bathroom extractor fan has been broken since summer and was reported twice.";
    base.suggested_human_action = "Check the work order history and call the resident today.";
  } else if (/\b(parking|neighbou?r|spot|2C)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "NEIGHBOURS";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
  } else if (/\b(relocat\w*|moving|move out|leaving|not renewing)\b/i.test(text)) {
    base.intent = "LEAVING";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
  } else if (/\b(depends|we'll see|rent|terms|price)\b/i.test(text) && !/\blove to stay|planning to stay|plan to stay\b/i.test(text)) {
    base.intent = "WAVERING";
    base.urgency = "MEDIUM";
    base.confidence = "MEDIUM";
  } else if (/^\s*k\s*$/i.test(text)) {
    base.intent = "UNCLEAR";
    base.confidence = "LOW";
    base.urgency = "LOW";
    base.grievance_present = false;
    base.grievance_category = "NONE";
  } else if (/\b(all good|planning to stay|plan to stay|love to stay|happy here|staying)\b/i.test(folded)) {
    base.intent = "STAYING";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.compliance_flag = "NONE";
    base.confidence = "HIGH";
    base.urgency = containsQuestion(text) ? "MEDIUM" : "LOW";
  }

  const question = containsQuestion(text);
  base.contains_question = question;
  base.requires_human = !(
    base.intent === "STAYING" &&
    base.grievance_present === false &&
    base.grievance_category === "NONE" &&
    base.compliance_flag === "NONE" &&
    base.confidence === "HIGH" &&
    question === false
  );
  if (base.compliance_flag !== "NONE" || base.intent === "OPT_OUT") base.requires_human = true;
  return base;
}

function baselineRawClassification() {
  return {
    intent: "UNCLEAR",
    grievance_present: false,
    grievance_summary: "",
    grievance_category: "NONE",
    urgency: "LOW",
    compliance_flag: "NONE",
    suggested_human_action: "Read the reply and follow up personally.",
    confidence: "LOW",
  };
}

function shouldUseFastDeterministicRoute(replyText) {
  const text = normalizeText(replyText);
  return /\b(stop emailing|stop|unsubscribe|remove me|do not contact|don't contact)\b/i.test(text) ||
    /\b(walker|wheelchair|disab|medical|grab bar|assistance animal|service animal|reasonable accommodation)\b/i.test(text) ||
    /\b(mould|mold|black mould|black mold|no heat|heat is out|hot water|sewage|pests?|electrical|gas leak|water ingress|leak|ceiling)\b/i.test(text) ||
    /\b(lawyer|attorney|lawsuit|sue|housing authority|code inspector|withhold(?:ing)? rent|formal complaint)\b/i.test(text) ||
    /\b(discriminat|unfair treatment|race|religion|national origin|familial status|source of income|language access)\b/i.test(text) ||
    /\b(extractor fan|bathroom fan|reported it twice|broken since summer)\b/i.test(text) ||
    /\b(parking|neighbou?r|spot|2C)\b/i.test(text) ||
    /\b(relocat\w*|moving|move out|leaving|not renewing)\b/i.test(text) ||
    /\b(depends|we'll see|rent|terms|price)\b/i.test(text) ||
    /^\s*k\s*$/i.test(text) ||
    /\b(all good|planning to stay|plan to stay|love to stay|happy here|staying)\b/i.test(text);
}

function routeStatusForClassification(classification) {
  if (classification.intent === "STAYING" && classification.requires_human === false) return "STAYING";
  if (classification.intent === "NO_SIGNAL") return "";
  return "AT_RISK";
}

function updateLeaseForRoute(lease, classification) {
  const status = routeStatusForClassification(classification);
  if (!status) return null;
  return {
    ...lease,
    status,
    opted_out: classification.intent === "OPT_OUT" || classification.compliance_flag === "OPT_OUT" ? true : lease.opted_out,
  };
}

function buildLogRow(workItem, classification, now, eventType) {
  return {
    event_id: workItem.event_id,
    lease_id: normalizeText(workItem.lease?.lease_id),
    event_type: eventType || "REPLY_CLASSIFIED",
    reply_text: normalizeText(workItem.reply?.reply_text),
    intent: classification.intent,
    grievance_category: classification.grievance_category,
    grievance_summary: classification.grievance_summary,
    urgency: classification.urgency,
    compliance_flag: classification.compliance_flag === "NONE" ? "" : classification.compliance_flag,
    confidence: classification.confidence,
    requires_human: classification.requires_human,
    created_at: now,
  };
}

function formatDate(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return normalizeText(value);
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function buildTelegramText(workItem, classification) {
  const lease = workItem.lease || {};
  const tenant = normalizeText(lease.tenant_name) || "Unmatched reply";
  const unit = normalizeText(lease.unit) || "No unit";
  const leaseEnd = formatDate(lease.lease_end_date);
  const days = normalizeText(lease.days_to_expiry);
  const badges = [
    classification.intent,
    classification.grievance_category !== "NONE" ? classification.grievance_category : "",
    classification.compliance_flag !== "NONE" ? classification.compliance_flag : "",
    classification.urgency,
  ].filter(Boolean).join(" / ");
  const complianceLine = classification.compliance_flag !== "NONE" ? "\nNo response was drafted." : "";
  return [
    `AT RISK - ${tenant}, ${unit}`,
    `Lease ends ${leaseEnd}${days ? ` / ${days} days out` : ""}`,
    "",
    badges,
    "",
    `"${normalizeText(workItem.reply?.reply_text)}"`,
    "",
    `Action: ${classification.suggested_human_action || "Read the reply and follow up personally."}`,
    `Confidence: ${classification.confidence}${complianceLine}`,
  ].join("\n");
}

function finalizeRoute(workItem, classification, now, eventType) {
  const leaseUpdate = workItem.lease?.lease_id ? updateLeaseForRoute(workItem.lease, classification) : null;
  const shouldAlert = classification.requires_human === true && classification.intent !== "NO_SIGNAL";
  const suppressed = normalizeBool(workItem._suppress_alerts);
  return {
    ok: true,
    action: "check_replies",
    source: workItem.source,
    processed_count: eventType === "NO_SIGNAL" ? 0 : 1,
    alerted_count: shouldAlert && !suppressed ? 1 : 0,
    duplicate_count: 0,
    no_signal_count: eventType === "NO_SIGNAL" ? 1 : 0,
    unmatched_count: eventType === "UNMATCHED_REPLY" ? 1 : 0,
    lease_id: normalizeText(workItem.lease?.lease_id),
    match_method: workItem.match_method || "",
    event_id: workItem.event_id,
    classification,
    _terminal: true,
    _needs_ai: false,
    _skip_lease_update: !leaseUpdate,
    _lease_update: leaseUpdate,
    _log_row: buildLogRow(workItem, classification, now, eventType),
    _should_alert: shouldAlert && !suppressed,
    _telegram_text: shouldAlert ? buildTelegramText(workItem, classification) : "",
    _telegram_chat_id: normalizeText(workItem.config?.telegram_chat_id),
    _gmail_message_id: workItem._gmail_message_id || "",
    _processed_label_id: workItem._processed_label_id || "",
    board_url: "http://localhost:5678/webhook/board",
  };
}

function finalizeAiRoute(workItem, openAiOutput, now) {
  if (openAiOutput && (openAiOutput.error || openAiOutput.errorMessage)) {
    return finalizeClassificationFailure(workItem, normalizeText(openAiOutput.error?.message || openAiOutput.errorMessage || openAiOutput.error), now);
  }
  let raw;
  try {
    raw = extractClassification(openAiOutput);
  } catch (_) {
    raw = {
      intent: "UNCLEAR",
      grievance_present: false,
      grievance_summary: "Classifier response wrapper was not recognized.",
      grievance_category: "NONE",
      urgency: "LOW",
      compliance_flag: "NONE",
      suggested_human_action: "Read the reply and follow up personally.",
      confidence: "LOW",
    };
  }
  const classification = deterministicClassification(workItem.reply.reply_text, raw);
  return finalizeRoute(workItem, classification, now, "REPLY_CLASSIFIED");
}

function finalizeClassificationFailure(workItem, errorMessage, now) {
  const classification = {
    intent: "CLASSIFY_FAILED",
    grievance_present: true,
    grievance_summary: `Classification unavailable: ${normalizeText(errorMessage).slice(0, 140)}`,
    grievance_category: "OTHER",
    urgency: "HIGH",
    compliance_flag: "NONE",
    suggested_human_action: "Read this reply directly because classification failed.",
    confidence: "LOW",
    contains_question: containsQuestion(workItem.reply?.reply_text),
    requires_human: true,
  };
  return finalizeRoute(workItem, classification, now, "CLASSIFY_FAILED");
}

function buildWorkItem(reply, prepared) {
  const workItem = prepareReplyWorkItem(reply, prepared.config, prepared.leases, prepared.log_rows);

  // The library decides routing itself: anything it did not mark _needs_ai has
  // already been finalized (duplicate, unmatched, auto-reply, or a deterministic
  // fast route) and must not be sent to the classifier.
  const needsAi = Boolean(workItem._needs_ai);

  // finalizeRoute() returns a summary that drops the reply and lease objects, so
  // both are re-attached here for the downstream card and Airtable write.
  const lease = workItem.lease && workItem.lease.lease_id
    ? workItem.lease
    : ((prepared.leases || []).find((row) => row.lease_id === workItem.lease_id) || null);

  return {
    json: Object.assign({}, workItem, {
      has_reply: true,
      is_terminal: !needsAi,
      needs_ai: needsAi,
      reply,
      lease,
      config: prepared.config,
      chat_id: prepared.chat_id,
      model: prepared.model,
      instructions: needsAi ? classificationInstructions() : '',
      prompt: needsAi ? buildClassificationPrompt(workItem) : '',
      waiting_count: prepared.waiting_count || 0,
    }),
  };
}


const prepared = $('Prepare Reply Source').first().json;
const reply = normalizeManualReply(prepared.manual_body || {});
return [buildWorkItem(reply, prepared)];

function flattenAirtable(items) {
  const out = [];
  for (const item of items || []) {
    const records = item && item.json && Array.isArray(item.json.records) ? item.json.records : [];
    for (const record of records) {
      out.push(Object.assign({ record_id: record.id }, record.fields || {}));
    }
  }
  return out;
}

function configMap(rows) {
  const map = {};
  for (const row of rows || []) {
    if (row.key) map[row.key] = row.value;
  }
  return map;
}

function toArray(value) {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

function normalizeText(value) {
  return value === null || value === undefined ? "" : String(value).trim();
}

function normalizeEmail(value) {
  return normalizeText(value).toLowerCase();
}

function normalizeBool(value) {
  if (value === true) return true;
  if (value === false) return false;
  return ["true", "1", "yes", "y"].includes(normalizeText(value).toLowerCase());
}

function buildConfig(configRows) {
  const config = {};
  for (const row of toArray(configRows)) {
    const key = normalizeText(row.key);
    if (key) config[key] = normalizeText(row.value);
  }
  return config;
}

function hashHex(value) {
  let hash = 2166136261;
  const text = normalizeText(value);
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).toUpperCase().padStart(8, "0");
}

function parseEmailAddress(value) {
  const text = normalizeText(value);
  const angleMatch = text.match(/<([^<>@\s]+@[^<>@\s]+)>/);
  if (angleMatch) return normalizeEmail(angleMatch[1]);
  const bareMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return bareMatch ? normalizeEmail(bareMatch[0]) : normalizeEmail(text);
}

function extractRefToken(value) {
  const match = normalizeText(value).match(/\[?(R-[0-9A-F]{4})\]?/i);
  return match ? match[1].toUpperCase() : "";
}

function stripHtml(value) {
  return normalizeText(value)
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/\s+\n/g, "\n")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function stripQuotedReply(value) {
  let text = stripHtml(value).replace(/\r\n/g, "\n");
  text = text.split(/\nOn .+ wrote:\s*$/im)[0];
  text = text.split(/\n-{2,}\s*Original Message\s*-{2,}/i)[0];
  text = text.split(/\nFrom:\s.+\nSent:\s.+\nTo:\s.+/i)[0];
  text = text
    .split("\n")
    .filter((line) => !normalizeText(line).startsWith(">"))
    .join("\n");
  text = text.split(/\n--\s*$/m)[0];
  text = text.split(/\nSent from my /i)[0];
  text = text.split(/\nThis message and any attachments/i)[0];
  return text.replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();
}

function hasManualReplyPayload(body) {
  return Boolean(
    normalizeText(body.reply_text || body.text || body.body || body.message) ||
    normalizeText(body.subject) ||
    normalizeText(body.from_email || body.from || body.sender),
  );
}

function headerValue(headers, name) {
  const target = normalizeText(name).toLowerCase();
  if (!headers) return "";
  if (Array.isArray(headers)) {
    const found = headers.find((header) => normalizeText(header.name).toLowerCase() === target);
    return found ? normalizeText(found.value) : "";
  }
  if (typeof headers === "object") {
    const key = Object.keys(headers).find((candidate) => normalizeText(candidate).toLowerCase() === target);
    return key ? normalizeText(headers[key]) : "";
  }
  return "";
}

function isAutoReply(reply) {
  const subject = normalizeText(reply.subject);
  const body = normalizeText(reply.reply_text);
  const headers = reply.headers || {};
  const autoSubmitted = headerValue(headers, "Auto-Submitted");
  const xAutoreply = headerValue(headers, "X-Autoreply");
  const precedence = headerValue(headers, "Precedence");

  if (autoSubmitted && !/^no$/i.test(autoSubmitted)) return true;
  if (xAutoreply) return true;
  if (/^(bulk|auto_reply|list)$/i.test(precedence)) return true;
  if (/\b(out of office|automatic reply|auto-?reply|delivery status notification|undeliverable|mail delivery failed)\b/i.test(subject)) return true;
  if (/\b(out of the office|out of office|limited access to email|currently away|automatic reply)\b/i.test(body)) return true;
  return false;
}

function containsQuestion(replyText) {
  const text = normalizeText(replyText);
  const questionWord = /\b(what|when|who|whom|whose|which|where|why|how|can|could|will|would|should|do|does|did|is|are|any chance|possible)\b/i;
  return /\?/.test(text) && questionWord.test(text);
}

function eventIdForReply(reply) {
  const messageId = normalizeText(reply.message_id || reply.id);
  if (messageId) return `reply-${messageId.replace(/[^A-Za-z0-9_.:-]/g, "-").slice(0, 96)}`;
  return `reply-${hashHex(`${reply.from_email}|${reply.subject}|${reply.reply_text}`)}`;
}

function findExistingEvent(logRows, eventId) {
  return toArray(logRows).some((row) => normalizeText(row.event_id) === eventId);
}

function matchLease(reply, leases) {
  const token = extractRefToken(`${reply.subject || ""} ${reply.reply_text || ""}`);
  if (token) {
    const tokenMatch = toArray(leases).find((lease) => normalizeText(lease.ref_token).toUpperCase() === token);
    if (tokenMatch) return { lease: tokenMatch, match_method: "ref_token", ref_token: token };
  }

  const fromEmail = normalizeEmail(reply.from_email);
  if (fromEmail) {
    const emailMatches = toArray(leases).filter((lease) => normalizeEmail(lease.email) === fromEmail);
    const sentFirst = emailMatches.find((lease) => ["SENT", "AT_RISK", "STAYING"].includes(normalizeText(lease.status).toUpperCase()));
    if (sentFirst) return { lease: sentFirst, match_method: "email", ref_token: normalizeText(sentFirst.ref_token) };
    if (emailMatches.length === 1) return { lease: emailMatches[0], match_method: "email", ref_token: normalizeText(emailMatches[0].ref_token) };
  }

  return { lease: null, match_method: "unmatched", ref_token: token };
}

function normalizeGmailMessage(message) {
  const headers = message.headers || message.payload?.headers || {};
  const subject = normalizeText(message.subject || headerValue(headers, "Subject"));
  const fromEmail = parseEmailAddress(message.from || headerValue(headers, "From"));
  const replyText = stripQuotedReply(message.textPlain || message.text || message.snippet || message.textHtml || message.html || "");
  return {
    source: "gmail",
    message_id: normalizeText(message.id || message.messageId),
    thread_id: normalizeText(message.threadId || message.thread_id),
    from_email: fromEmail,
    subject,
    reply_text: replyText,
    headers,
    raw: message,
  };
}

function normalizeManualReply(body) {
  const replyText = stripQuotedReply(body.reply_text || body.text || body.body || body.message || "");
  return {
    source: "manual",
    message_id: normalizeText(body.message_id || body.id || body.fixture_id),
    thread_id: normalizeText(body.thread_id),
    from_email: parseEmailAddress(body.from_email || body.from || body.sender || ""),
    subject: normalizeText(body.subject || ""),
    reply_text: replyText,
    headers: body.headers || {},
    suppress_alerts: normalizeBool(body.suppress_alerts),
    raw: body,
  };
}

function noReplyResult(config, sourceMode) {
  return {
    ok: true,
    action: "check_replies",
    source: sourceMode || "gmail",
    processed_count: 0,
    alerted_count: 0,
    duplicate_count: 0,
    no_signal_count: 0,
    unmatched_count: 0,
    message: "No unprocessed replies found.",
    board_url: "http://localhost:5678/webhook/board",
    _terminal: true,
    _skip_log: true,
    _skip_lease_update: true,
  };
}

function prepareReplyWorkItem(reply, config, leases, logRows) {
  const eventId = eventIdForReply(reply);
  const duplicate = findExistingEvent(logRows, eventId);
  const base = {
    ok: true,
    action: "check_replies",
    source: reply.source,
    event_id: eventId,
    reply,
    config,
    board_url: "http://localhost:5678/webhook/board",
    _processed_label_id: normalizeText(config.gmail_processed_label_id || config.processed_label_id || reply.processed_label_id),
    _gmail_message_id: reply.source === "gmail" ? normalizeText(reply.message_id) : "",
    _suppress_alerts: normalizeBool(reply.suppress_alerts),
  };

  if (!normalizeText(reply.reply_text) && !normalizeText(reply.subject)) {
    return noReplyResult(config, reply.source);
  }

  if (duplicate) {
    return {
      ...base,
      processed_count: 0,
      alerted_count: 0,
      duplicate_count: 1,
      no_signal_count: 0,
      unmatched_count: 0,
      duplicate: true,
      message: "Reply already processed.",
      _terminal: true,
      _skip_log: true,
      _skip_lease_update: true,
    };
  }

  const match = matchLease(reply, leases);
  if (!match.lease) {
    const classification = {
      intent: "UNMATCHED",
      grievance_present: false,
      grievance_summary: "Reply could not be matched to a lease.",
      grievance_category: "NONE",
      urgency: "HIGH",
      compliance_flag: "NONE",
      suggested_human_action: "Find the tenant manually before replying.",
      confidence: "LOW",
      contains_question: containsQuestion(reply.reply_text),
      requires_human: true,
    };
    return finalizeRoute({ ...base, lease: {}, match_method: "unmatched" }, classification, new Date().toISOString(), "UNMATCHED_REPLY");
  }

  const matched = { ...base, lease: match.lease, match_method: match.match_method, ref_token: match.ref_token };
  if (isAutoReply(reply)) {
    const classification = {
      intent: "NO_SIGNAL",
      grievance_present: false,
      grievance_summary: "",
      grievance_category: "NONE",
      urgency: "LOW",
      compliance_flag: "NONE",
      suggested_human_action: "No action needed.",
      confidence: "HIGH",
      contains_question: false,
      requires_human: false,
    };
    return finalizeRoute(matched, classification, new Date().toISOString(), "NO_SIGNAL");
  }

  if (shouldUseFastDeterministicRoute(reply.reply_text)) {
    const classification = deterministicClassification(reply.reply_text, baselineRawClassification());
    return finalizeRoute(matched, classification, new Date().toISOString(), "REPLY_CLASSIFIED");
  }

  return {
    ...matched,
    _needs_ai: true,
    model_classify: normalizeText(config.model_classify) || "gpt-5.6-luna",
    instructions: classificationInstructions(),
    prompt: buildClassificationPrompt(matched),
  };
}

function classificationInstructions() {
  return [
    "You classify a single reply from a residential tenant to a short check-in message from their property manager.",
    "You are only a classifier. Never write a reply, never give advice to the tenant, and never contact anyone.",
    "Output JSON matching the schema exactly. No prose, markdown, or fences.",
    "If a reply both raises a problem and says they are staying, use GRIEVANCE. The problem matters more than the intent.",
    "Set compliance_flag precisely. ACCOMMODATION_REQUEST covers disability, medical, mobility, assistance animal, or home modification needs. HABITABILITY covers mould, heat, hot water, sewage, pests, hazards, leaks, and safety risks. LEGAL_THREAT covers lawyer, lawsuit, code inspector, housing authority, withholding rent, or formal complaint. OPT_OUT covers stop, unsubscribe, remove me, or do not contact. DISCRIMINATION_CONCERN covers unequal treatment tied to protected-class language.",
    "suggested_human_action must be one short imperative sentence addressed to the property manager, never the tenant.",
    "confidence is HIGH only if the reply is unambiguous. Short, sarcastic, mixed, or quoted replies are MEDIUM or LOW.",
  ].join("\n");
}

function buildClassificationPrompt(workItem) {
  const lease = workItem.lease || {};
  return [
    "Classify this tenant reply.",
    "",
    `Tenant first name: ${normalizeText(lease.tenant_first_name)}`,
    `Unit: ${normalizeText(lease.unit)}`,
    `Lease end date: ${normalizeText(lease.lease_end_date)}`,
    `Subject: ${normalizeText(workItem.reply.subject)}`,
    "",
    "Reply:",
    normalizeText(workItem.reply.reply_text),
  ].join("\n");
}

function extractJsonObject(value) {
  if (!value) return null;
  if (typeof value === "object" && !Array.isArray(value)) return value;
  const text = normalizeText(value);
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch (_) {
    const match = text.match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch (__) {
      return null;
    }
  }
}

function extractClassification(openAiOutput) {
  const direct = extractJsonObject(openAiOutput);
  if (direct && direct.intent) return direct;

  const queue = [openAiOutput];
  const seen = new Set();
  while (queue.length) {
    const current = queue.shift();
    if (!current || seen.has(current)) continue;
    if (typeof current === "object") seen.add(current);
    if (typeof current === "string") {
      const parsed = extractJsonObject(current);
      if (parsed && parsed.intent) return parsed;
      continue;
    }
    if (Array.isArray(current)) {
      queue.push(...current);
      continue;
    }
    if (typeof current === "object") {
      if (current.intent) return current;
      for (const key of ["output", "text", "content", "message", "data", "response", "json"]) {
        if (Object.prototype.hasOwnProperty.call(current, key)) queue.push(current[key]);
      }
    }
  }
  throw new Error("OpenAI classification output did not contain schema JSON.");
}

function cleanEnum(value, allowed, fallback) {
  const normalized = normalizeText(value).toUpperCase();
  return allowed.includes(normalized) ? normalized : fallback;
}

function deterministicClassification(replyText, raw) {
  const text = normalizeText(replyText);
  const folded = text.toLowerCase();
  const base = {
    intent: cleanEnum(raw.intent, ["STAYING", "WAVERING", "LEAVING", "GRIEVANCE", "UNCLEAR", "NO_SIGNAL", "OPT_OUT"], "UNCLEAR"),
    grievance_present: normalizeBool(raw.grievance_present),
    grievance_summary: normalizeText(raw.grievance_summary),
    grievance_category: cleanEnum(raw.grievance_category, ["NONE", "MAINTENANCE", "NEIGHBOURS", "FEES", "COMMUNICATION", "PROPERTY_CONDITION", "OTHER"], "NONE"),
    urgency: cleanEnum(raw.urgency, ["HIGH", "MEDIUM", "LOW"], "LOW"),
    compliance_flag: cleanEnum(raw.compliance_flag, ["NONE", "ACCOMMODATION_REQUEST", "HABITABILITY", "LEGAL_THREAT", "OPT_OUT", "DISCRIMINATION_CONCERN"], "NONE"),
    suggested_human_action: normalizeText(raw.suggested_human_action) || "Read the reply and follow up personally.",
    confidence: cleanEnum(raw.confidence, ["HIGH", "MEDIUM", "LOW"], "LOW"),
  };

  if (/\b(stop emailing|stop|unsubscribe|remove me|do not contact|don't contact)\b/i.test(text)) {
    base.intent = "OPT_OUT";
    base.compliance_flag = "OPT_OUT";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.suggested_human_action = "Mark the resident opted out and follow up only if required.";
  } else if (/\b(walker|wheelchair|disab|medical|grab bar|assistance animal|service animal|reasonable accommodation)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = base.grievance_category === "NONE" ? "PROPERTY_CONDITION" : base.grievance_category;
    base.compliance_flag = "ACCOMMODATION_REQUEST";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.suggested_human_action = "Review this as an accommodation request before responding.";
  } else if (/\b(mould|mold|black mould|black mold|no heat|heat is out|hot water|sewage|pests?|electrical|gas leak|water ingress|leak|ceiling)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "PROPERTY_CONDITION";
    base.compliance_flag = "HABITABILITY";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.suggested_human_action = "Escalate this condition issue for human review today.";
  } else if (/\b(lawyer|attorney|lawsuit|sue|housing authority|code inspector|withhold(?:ing)? rent|formal complaint)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.compliance_flag = "LEGAL_THREAT";
    base.urgency = "HIGH";
    base.suggested_human_action = "Escalate this legal-risk reply before responding.";
  } else if (/\b(discriminat|unfair treatment|race|religion|national origin|familial status|source of income|language access)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.compliance_flag = "DISCRIMINATION_CONCERN";
    base.urgency = "HIGH";
    base.suggested_human_action = "Escalate this fair-housing concern before responding.";
  } else if (/\b(extractor fan|bathroom fan|reported it twice|broken since summer)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "MAINTENANCE";
    base.compliance_flag = "NONE";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
    base.grievance_summary = "Bathroom extractor fan has been broken since summer and was reported twice.";
    base.suggested_human_action = "Check the work order history and call the resident today.";
  } else if (/\b(parking|neighbou?r|spot|2C)\b/i.test(text)) {
    base.intent = "GRIEVANCE";
    base.grievance_present = true;
    base.grievance_category = "NEIGHBOURS";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
  } else if (/\b(relocat\w*|moving|move out|leaving|not renewing)\b/i.test(text)) {
    base.intent = "LEAVING";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.urgency = "HIGH";
    base.confidence = "HIGH";
  } else if (/\b(depends|we'll see|rent|terms|price)\b/i.test(text) && !/\blove to stay|planning to stay|plan to stay\b/i.test(text)) {
    base.intent = "WAVERING";
    base.urgency = "MEDIUM";
    base.confidence = "MEDIUM";
  } else if (/^\s*k\s*$/i.test(text)) {
    base.intent = "UNCLEAR";
    base.confidence = "LOW";
    base.urgency = "LOW";
    base.grievance_present = false;
    base.grievance_category = "NONE";
  } else if (/\b(all good|planning to stay|plan to stay|love to stay|happy here|staying)\b/i.test(folded)) {
    base.intent = "STAYING";
    base.grievance_present = false;
    base.grievance_category = "NONE";
    base.compliance_flag = "NONE";
    base.confidence = "HIGH";
    base.urgency = containsQuestion(text) ? "MEDIUM" : "LOW";
  }

  const question = containsQuestion(text);
  base.contains_question = question;
  base.requires_human = !(
    base.intent === "STAYING" &&
    base.grievance_present === false &&
    base.grievance_category === "NONE" &&
    base.compliance_flag === "NONE" &&
    base.confidence === "HIGH" &&
    question === false
  );
  if (base.compliance_flag !== "NONE" || base.intent === "OPT_OUT") base.requires_human = true;
  return base;
}

function baselineRawClassification() {
  return {
    intent: "UNCLEAR",
    grievance_present: false,
    grievance_summary: "",
    grievance_category: "NONE",
    urgency: "LOW",
    compliance_flag: "NONE",
    suggested_human_action: "Read the reply and follow up personally.",
    confidence: "LOW",
  };
}

function shouldUseFastDeterministicRoute(replyText) {
  const text = normalizeText(replyText);
  return /\b(stop emailing|stop|unsubscribe|remove me|do not contact|don't contact)\b/i.test(text) ||
    /\b(walker|wheelchair|disab|medical|grab bar|assistance animal|service animal|reasonable accommodation)\b/i.test(text) ||
    /\b(mould|mold|black mould|black mold|no heat|heat is out|hot water|sewage|pests?|electrical|gas leak|water ingress|leak|ceiling)\b/i.test(text) ||
    /\b(lawyer|attorney|lawsuit|sue|housing authority|code inspector|withhold(?:ing)? rent|formal complaint)\b/i.test(text) ||
    /\b(discriminat|unfair treatment|race|religion|national origin|familial status|source of income|language access)\b/i.test(text) ||
    /\b(extractor fan|bathroom fan|reported it twice|broken since summer)\b/i.test(text) ||
    /\b(parking|neighbou?r|spot|2C)\b/i.test(text) ||
    /\b(relocat\w*|moving|move out|leaving|not renewing)\b/i.test(text) ||
    /\b(depends|we'll see|rent|terms|price)\b/i.test(text) ||
    /^\s*k\s*$/i.test(text) ||
    /\b(all good|planning to stay|plan to stay|love to stay|happy here|staying)\b/i.test(text);
}

function routeStatusForClassification(classification) {
  if (classification.intent === "STAYING" && classification.requires_human === false) return "STAYING";
  if (classification.intent === "NO_SIGNAL") return "";
  return "AT_RISK";
}

function updateLeaseForRoute(lease, classification) {
  const status = routeStatusForClassification(classification);
  if (!status) return null;
  return {
    ...lease,
    status,
    opted_out: classification.intent === "OPT_OUT" || classification.compliance_flag === "OPT_OUT" ? true : lease.opted_out,
  };
}

function buildLogRow(workItem, classification, now, eventType) {
  return {
    event_id: workItem.event_id,
    lease_id: normalizeText(workItem.lease?.lease_id),
    event_type: eventType || "REPLY_CLASSIFIED",
    reply_text: normalizeText(workItem.reply?.reply_text),
    intent: classification.intent,
    grievance_category: classification.grievance_category,
    grievance_summary: classification.grievance_summary,
    urgency: classification.urgency,
    compliance_flag: classification.compliance_flag === "NONE" ? "" : classification.compliance_flag,
    confidence: classification.confidence,
    requires_human: classification.requires_human,
    created_at: now,
  };
}

function formatDate(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return normalizeText(value);
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

function buildTelegramText(workItem, classification) {
  const lease = workItem.lease || {};
  const tenant = normalizeText(lease.tenant_name) || "Unmatched reply";
  const unit = normalizeText(lease.unit) || "No unit";
  const leaseEnd = formatDate(lease.lease_end_date);
  const days = normalizeText(lease.days_to_expiry);
  const badges = [
    classification.intent,
    classification.grievance_category !== "NONE" ? classification.grievance_category : "",
    classification.compliance_flag !== "NONE" ? classification.compliance_flag : "",
    classification.urgency,
  ].filter(Boolean).join(" / ");
  const complianceLine = classification.compliance_flag !== "NONE" ? "\nNo response was drafted." : "";
  return [
    `AT RISK - ${tenant}, ${unit}`,
    `Lease ends ${leaseEnd}${days ? ` / ${days} days out` : ""}`,
    "",
    badges,
    "",
    `"${normalizeText(workItem.reply?.reply_text)}"`,
    "",
    `Action: ${classification.suggested_human_action || "Read the reply and follow up personally."}`,
    `Confidence: ${classification.confidence}${complianceLine}`,
  ].join("\n");
}

function finalizeRoute(workItem, classification, now, eventType) {
  const leaseUpdate = workItem.lease?.lease_id ? updateLeaseForRoute(workItem.lease, classification) : null;
  const shouldAlert = classification.requires_human === true && classification.intent !== "NO_SIGNAL";
  const suppressed = normalizeBool(workItem._suppress_alerts);
  return {
    ok: true,
    action: "check_replies",
    source: workItem.source,
    processed_count: eventType === "NO_SIGNAL" ? 0 : 1,
    alerted_count: shouldAlert && !suppressed ? 1 : 0,
    duplicate_count: 0,
    no_signal_count: eventType === "NO_SIGNAL" ? 1 : 0,
    unmatched_count: eventType === "UNMATCHED_REPLY" ? 1 : 0,
    lease_id: normalizeText(workItem.lease?.lease_id),
    match_method: workItem.match_method || "",
    event_id: workItem.event_id,
    classification,
    _terminal: true,
    _needs_ai: false,
    _skip_lease_update: !leaseUpdate,
    _lease_update: leaseUpdate,
    _log_row: buildLogRow(workItem, classification, now, eventType),
    _should_alert: shouldAlert && !suppressed,
    _telegram_text: shouldAlert ? buildTelegramText(workItem, classification) : "",
    _telegram_chat_id: normalizeText(workItem.config?.telegram_chat_id),
    _gmail_message_id: workItem._gmail_message_id || "",
    _processed_label_id: workItem._processed_label_id || "",
    board_url: "http://localhost:5678/webhook/board",
  };
}

function finalizeAiRoute(workItem, openAiOutput, now) {
  if (openAiOutput && (openAiOutput.error || openAiOutput.errorMessage)) {
    return finalizeClassificationFailure(workItem, normalizeText(openAiOutput.error?.message || openAiOutput.errorMessage || openAiOutput.error), now);
  }
  let raw;
  try {
    raw = extractClassification(openAiOutput);
  } catch (_) {
    raw = {
      intent: "UNCLEAR",
      grievance_present: false,
      grievance_summary: "Classifier response wrapper was not recognized.",
      grievance_category: "NONE",
      urgency: "LOW",
      compliance_flag: "NONE",
      suggested_human_action: "Read the reply and follow up personally.",
      confidence: "LOW",
    };
  }
  const classification = deterministicClassification(workItem.reply.reply_text, raw);
  return finalizeRoute(workItem, classification, now, "REPLY_CLASSIFIED");
}

function finalizeClassificationFailure(workItem, errorMessage, now) {
  const classification = {
    intent: "CLASSIFY_FAILED",
    grievance_present: true,
    grievance_summary: `Classification unavailable: ${normalizeText(errorMessage).slice(0, 140)}`,
    grievance_category: "OTHER",
    urgency: "HIGH",
    compliance_flag: "NONE",
    suggested_human_action: "Read this reply directly because classification failed.",
    confidence: "LOW",
    contains_question: containsQuestion(workItem.reply?.reply_text),
    requires_human: true,
  };
  return finalizeRoute(workItem, classification, now, "CLASSIFY_FAILED");
}
/**
 * Telegram card and inline-keyboard builders for the v2 demo.
 *
 * This file is inlined into n8n Code nodes at import time, the same way the v1
 * stage libraries are, so it must stay dependency-free and browser-safe.
 *
 * Telegram constraints enforced here:
 *  - callback_data must be 64 bytes or fewer. Actions use 3-character prefixes
 *    plus an Airtable record id (17 chars), so the longest payload is ~21 bytes.
 *  - message text must be 4096 characters or fewer. Long drafts are truncated
 *    for display only; the stored draft is never shortened.
 *  - only one Telegram Trigger may be active per bot, so every button in this
 *    file is routed through WF6.
 */

const CALLBACK_MAX_BYTES = 64;
const MESSAGE_MAX_CHARS = 4096;

const ACTIONS = {
  APPROVE_SEND: "apv",
  SKIP_DRAFT: "skp",
  NEXT_DRAFT: "nxt",
  DRAFT_ASSIST: "ast",
  SEND_ASSIST: "snd",
  DISCARD_ASSIST: "dis",
  MARK_RESOLVED: "res",
  SEND_CONFIRMATION: "cnf",
  ACK_HANDOFF: "hnd",
  EDIT_DRAFT: "edt",
};

function textOf(value) {
  return value == null ? "" : String(value).trim();
}

function escapeHtml(value) {
  return textOf(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function truncate(value, limit) {
  const text = textOf(value);
  if (text.length <= limit) return text;
  return `${text.slice(0, Math.max(0, limit - 1))}…`;
}

/** Encodes a button payload and fails loudly rather than letting Telegram reject it. */
function encodeCallback(action, recordId) {
  const payload = `${action}:${textOf(recordId)}`;
  const size = Buffer.byteLength(payload, "utf8");
  if (size > CALLBACK_MAX_BYTES) {
    throw new Error(`callback_data is ${size} bytes, over Telegram's ${CALLBACK_MAX_BYTES}-byte cap: ${payload}`);
  }
  return payload;
}

function decodeCallback(callbackData) {
  const raw = textOf(callbackData);
  const separator = raw.indexOf(":");
  if (separator === -1) return { action: raw, record_id: "" };
  return {
    action: raw.slice(0, separator),
    record_id: raw.slice(separator + 1),
  };
}

function keyboard(rows) {
  return { inline_keyboard: rows.filter((row) => row && row.length) };
}

function button(label, action, recordId) {
  return { text: label, callback_data: encodeCallback(action, recordId) };
}

function formatDate(value) {
  const text = textOf(value);
  if (!text) return "unknown";
  const parsed = new Date(text);
  if (Number.isNaN(parsed.getTime())) return text;
  return parsed.toISOString().slice(0, 10);
}

function formatMoney(value) {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount)) return "$0";
  return `$${Math.round(amount).toLocaleString("en-US")}`;
}

function badgeLine(lease) {
  return [
    textOf(lease.intent),
    textOf(lease.grievance_category) && textOf(lease.grievance_category) !== "NONE"
      ? textOf(lease.grievance_category)
      : "",
    textOf(lease.compliance_flag) && textOf(lease.compliance_flag) !== "NONE"
      ? textOf(lease.compliance_flag)
      : "",
    textOf(lease.urgency),
  ]
    .filter(Boolean)
    .join(" / ");
}

function residentHeader(lease) {
  const days = textOf(lease.days_to_expiry);
  const leaseEnd = formatDate(lease.lease_end_date);
  const tenure = textOf(lease.tenure_months);
  const parts = [`Lease ends ${leaseEnd}`];
  if (days) parts.push(`${days} days out`);
  if (tenure) parts.push(`${tenure} months resident`);
  return parts.join(" · ");
}

/* ------------------------------------------------------------------ cards */

/**
 * Summary posted once per generation run, before the individual draft cards.
 */
function generationSummaryCard(summary) {
  const lines = [
    `<b>${escapeHtml(summary.touch_label || "Check-ins")} drafted</b>`,
    "",
    `${summary.drafted_count} ready for review`,
  ];

  if (summary.review_failed_count) {
    lines.push(`${summary.review_failed_count} need wording (checks failed twice)`);
  }
  if (summary.handoff_count) {
    lines.push(`${summary.handoff_count} flagged for leasing handoff (no resident email)`);
  }
  if (summary.exposure != null) {
    lines.push("", `Turnover exposure in this window: <b>${formatMoney(summary.exposure)}</b>`);
  }

  lines.push("", "Nothing sends until you approve it.");

  return {
    text: lines.join("\n"),
    reply_markup: summary.first_record_id
      ? keyboard([[button("▶️ Review first draft", ACTIONS.NEXT_DRAFT, summary.first_record_id)]])
      : undefined,
  };
}

/**
 * A single draft awaiting approval. This is the core approval moment.
 */
function draftApprovalCard(lease, options = {}) {
  const lines = [
    `<b>${escapeHtml(lease.tenant_name)} · ${escapeHtml(lease.unit)}</b>`,
    residentHeader(lease),
    "",
    `<b>Subject:</b> ${escapeHtml(lease.draft_subject)}`,
    "",
    escapeHtml(truncate(lease.draft_body, 2400)),
  ];

  if (options.position && options.total) {
    lines.push("", `Draft ${options.position} of ${options.total}`);
  }

  const rows = [
    [
      button("✅ Approve & Send", ACTIONS.APPROVE_SEND, lease.record_id),
      button("⏭ Skip", ACTIONS.SKIP_DRAFT, lease.record_id),
    ],
  ];

  if (options.next_record_id) {
    rows.push([button("➡️ Next draft", ACTIONS.NEXT_DRAFT, options.next_record_id)]);
  }

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS), reply_markup: keyboard(rows) };
}

/**
 * A draft that failed guardrails twice. Deliberately has no approve button.
 */
function reviewFailedCard(lease) {
  return {
    text: [
      `<b>Needs wording · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
      "",
      `The draft failed the safety checks twice: ${escapeHtml(lease.data_quality || "see workflow log")}`,
      "",
      "No approve button is offered. Write this one yourself.",
    ].join("\n"),
  };
}

/**
 * 30-day cohort handoff. Internal only - never emails the resident.
 */
function leasingHandoffCard(leases) {
  const lines = [
    `<b>Leasing handoff · ${leases.length} residents at 30 days</b>`,
    "",
    "These are inside the renewal-offer window. No resident email is sent from here — this is a handoff to your leasing team.",
    "",
  ];

  leases.slice(0, 15).forEach((lease) => {
    lines.push(`• ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)} — ends ${formatDate(lease.lease_end_date)}`);
  });

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS) };
}

/**
 * A reply that needs a person. Mirrors the v1 alert content and adds actions.
 */
function atRiskAlertCard(lease, options = {}) {
  const complianceFlag = textOf(lease.compliance_flag);
  const isCompliance = complianceFlag && complianceFlag !== "NONE";

  const lines = [
    `<b>AT RISK · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
    residentHeader(lease),
    "",
    badgeLine(lease),
    "",
    `<i>"${escapeHtml(truncate(lease.reply_text, 1200))}"</i>`,
    "",
    `<b>Action:</b> ${escapeHtml(lease.suggested_action)}`,
    `Confidence: ${escapeHtml(lease.confidence)}`,
  ];

  if (isCompliance) {
    lines.push("", "<b>No response was drafted.</b>");
  }

  const rows = [];

  // Compliance-sensitive replies get no one-tap assist. A person decides first.
  if (!isCompliance) {
    rows.push([button("✍️ Draft my reply", ACTIONS.DRAFT_ASSIST, lease.record_id)]);
  }
  if (options.allow_resolve !== false) {
    rows.push([button("✅ Mark resolved", ACTIONS.MARK_RESOLVED, lease.record_id)]);
  }

  return {
    text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS),
    reply_markup: rows.length ? keyboard(rows) : undefined,
  };
}

/**
 * A drafted reply to the resident, awaiting explicit approval before it sends.
 */
function assistApprovalCard(lease) {
  return {
    text: truncate(
      [
        `<b>Suggested reply · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
        "",
        escapeHtml(truncate(lease.assist_draft, 2800)),
        "",
        "This has not been sent. Approve it and it goes to the resident as written.",
      ].join("\n"),
      MESSAGE_MAX_CHARS
    ),
    reply_markup: keyboard([
      [
        button("✅ Send reply", ACTIONS.SEND_ASSIST, lease.record_id),
        button("⏭ Discard", ACTIONS.DISCARD_ASSIST, lease.record_id),
      ],
    ]),
  };
}

/**
 * Confirmation that the issue is closed, plus the optional resident follow-up.
 */
function resolutionCard(lease, options = {}) {
  const lines = [
    `<b>Issue resolved · ${escapeHtml(lease.tenant_name)}, ${escapeHtml(lease.unit)}</b>`,
    "",
  ];

  if (lease.days_to_resolve != null && lease.days_to_resolve !== "") {
    lines.push(`Closed in ${lease.days_to_resolve} days.`);
  }
  if (options.exposure_recovered != null) {
    lines.push(`Turnover exposure recovered: <b>${formatMoney(options.exposure_recovered)}</b>`);
  }

  if (textOf(lease.assist_draft)) {
    lines.push("", "<b>Follow-up ready for the resident:</b>", "", escapeHtml(truncate(lease.assist_draft, 2000)));
    return {
      text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS),
      reply_markup: keyboard([
        [
          button("✅ Send confirmation", ACTIONS.SEND_CONFIRMATION, lease.record_id),
          button("⏭ Skip", ACTIONS.DISCARD_ASSIST, lease.record_id),
        ],
      ]),
    };
  }

  return { text: truncate(lines.join("\n"), MESSAGE_MAX_CHARS) };
}

/**
 * A reply that could not be matched to a resident. Never guesses an owner.
 */
function unmatchedReplyCard(reply) {
  return {
    text: truncate(
      [
        "<b>Unmatched reply</b>",
        "",
        `From: ${escapeHtml(reply.from_email || "unknown sender")}`,
        `Subject: ${escapeHtml(reply.subject || "(none)")}`,
        "",
        `<i>"${escapeHtml(truncate(reply.reply_text, 1000))}"</i>`,
        "",
        "No reference code matched and the sender is not in the roster. No resident was assigned. Find the resident manually before replying.",
      ].join("\n"),
      MESSAGE_MAX_CHARS
    ),
  };
}

/** Daily sweep digest. */
function sweepDigestCard(summary) {
  return {
    text: [
      `<b>${escapeHtml(summary.company_name || "Portfolio")} daily sweep</b>`,
      "",
      `${summary.recomputed_count} residents checked`,
      `${summary.at_risk_count} at risk · ${summary.staying_count} staying · ${summary.escalated_count} newly escalated`,
      `${summary.issues_resolved || 0} issues resolved`,
      "",
      `Exposure open: <b>${formatMoney(summary.turnover_exposure)}</b>`,
      `Exposure recovered: <b>${formatMoney(summary.exposure_recovered)}</b>`,
    ].join("\n"),
  };
}

/** Short acknowledgement text shown in Telegram's toast after a button press. */
function acknowledgement(action, outcome) {
  const map = {
    [ACTIONS.APPROVE_SEND]: outcome === "already_sent" ? "Already sent" : "Approved and sent",
    [ACTIONS.SKIP_DRAFT]: "Skipped",
    [ACTIONS.NEXT_DRAFT]: "Loading next draft",
    [ACTIONS.DRAFT_ASSIST]: "Drafting a reply",
    [ACTIONS.SEND_ASSIST]: outcome === "already_sent" ? "Already sent" : "Reply sent",
    [ACTIONS.DISCARD_ASSIST]: "Discarded",
    [ACTIONS.MARK_RESOLVED]: "Marked resolved",
    [ACTIONS.SEND_CONFIRMATION]: outcome === "already_sent" ? "Already sent" : "Confirmation sent",
    [ACTIONS.ACK_HANDOFF]: "Acknowledged",
    [ACTIONS.EDIT_DRAFT]: "Waiting for your wording",
  };
  return map[action] || "Done";
}
/**
 * Demo scoreboard maths for the v2 Metrics table and the Telegram digest.
 *
 * The headline number is turnover exposure: the money at risk in the residents
 * currently flagged AT_RISK or ESCALATE, valued at config.avg_turnover_cost.
 * Exposure recovered is the same figure for issues a manager has closed.
 *
 * These are demo-grade proxies, not a financial model. The POC does not claim a
 * resolved issue guarantees a renewal - only that the exposure was surfaced and
 * acted on. Say that out loud when presenting the number.
 *
 * This file is inlined into n8n Code nodes at import time.
 */

const AT_RISK_STATUSES = new Set(["AT_RISK", "ESCALATE"]);

function txt(value) {
  return value == null ? "" : String(value).trim();
}

function num(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function round1(value) {
  return Math.round(value * 10) / 10;
}

/**
 * @param {Array} leases  every lease row
 * @param {Array} logRows every outreach log row
 * @param {object} config config key/value map
 */
function computeMetrics(leases, logRows, config = {}) {
  const rows = leases || [];
  const log = logRows || [];
  const turnoverCost = num(config.avg_turnover_cost, 3900);

  const residentsInWindow = rows.filter((lease) => txt(lease.cohort) === "90").length;

  const checkInsSent = log.filter((row) => txt(row.event_type) === "SENT").length;
  const repliesReceived = log.filter((row) => txt(row.event_type) === "REPLY_RECEIVED").length;

  const issuesOpen = rows.filter((lease) => txt(lease.issue_status) === "OPEN");
  const issuesResolved = rows.filter((lease) => txt(lease.issue_status) === "RESOLVED");
  const issuesFound = issuesOpen.length + issuesResolved.length;

  const atRisk = rows.filter((lease) => AT_RISK_STATUSES.has(txt(lease.status).toUpperCase()));
  const staying = rows.filter((lease) => txt(lease.status).toUpperCase() === "STAYING");

  const resolutionDays = issuesResolved
    .map((lease) => num(lease.days_to_resolve, null))
    .filter((value) => value != null && Number.isFinite(value));

  const avgResolutionDays = resolutionDays.length
    ? round1(resolutionDays.reduce((sum, value) => sum + value, 0) / resolutionDays.length)
    : 0;

  return {
    snapshot: "current",
    residents_in_window: residentsInWindow,
    check_ins_sent: checkInsSent,
    replies_received: repliesReceived,
    issues_found: issuesFound,
    issues_resolved: issuesResolved.length,
    avg_resolution_days: avgResolutionDays,
    at_risk_count: atRisk.length,
    staying_count: staying.length,
    turnover_exposure: atRisk.length * turnoverCost,
    exposure_recovered: issuesResolved.length * turnoverCost,
    updated_at: new Date().toISOString(),
  };
}

/**
 * Exposure for a cohort before anything has been sent - used in the generation
 * summary card so the prospect sees a number at the very start of the demo.
 */
function windowExposure(leases, cohort, config = {}) {
  const turnoverCost = num(config.avg_turnover_cost, 3900);
  const count = (leases || []).filter((lease) => txt(lease.cohort) === txt(cohort)).length;
  return count * turnoverCost;
}

/** Fields written to the Metrics table (strips the digest-only keys). */
function toMetricsRecord(metrics) {
  return {
    snapshot: metrics.snapshot || "current",
    residents_in_window: metrics.residents_in_window,
    check_ins_sent: metrics.check_ins_sent,
    replies_received: metrics.replies_received,
    issues_found: metrics.issues_found,
    issues_resolved: metrics.issues_resolved,
    avg_resolution_days: metrics.avg_resolution_days,
    at_risk_count: metrics.at_risk_count,
    turnover_exposure: metrics.turnover_exposure,
    exposure_recovered: metrics.exposure_recovered,
    updated_at: metrics.updated_at,
  };
}

const selected = $('If Needs AI Classification').first().json;
const nowIso = new Date().toISOString();

if (!selected.has_reply) {
  return [{
    json: {
      has_writes: false,
      card_type: selected.silent ? 'none' : 'plain',
      chat_id: selected.chat_id,
      record_id: '',
      text: 'No new replies were found.',
      processed_count: 0,
      alerted_count: 0,
      ok: true,
    },
  }];
}

let routed;
if (selected.is_terminal) {
  routed = selected;
} else if (selected.needs_ai) {
  let aiOutput = null;
  try {
    aiOutput = $('OpenAI Classify Reply').first().json;
  } catch (error) {
    aiOutput = null;
  }
  routed = finalizeAiRoute(selected, aiOutput, nowIso);
} else {
  routed = selected;
}

const lease = routed.lease || selected.lease || null;
const classification = routed.classification || {};
const reply = routed.reply || selected.reply || {};
const isUnmatched = !lease;

const writes = [];
let cardType = 'plain';
let text = routed.message || 'Reply processed.';
let recordId = lease ? lease.record_id : '';

if (isUnmatched) {
  const card = unmatchedReplyCard(reply);
  text = card.text;
  cardType = 'plain';
} else {
  const complianceFlag = String(classification.compliance_flag || 'NONE');
  const isCompliance = complianceFlag && complianceFlag !== 'NONE';
  const intent = String(classification.intent || 'UNCLEAR');
  const requiresHuman = classification.requires_human === true;

  const fields = {
    reply_text: String(reply.reply_text || '').slice(0, 9000),
    intent,
    grievance_category: String(classification.grievance_category || 'NONE'),
    urgency: String(classification.urgency || 'LOW'),
    compliance_flag: complianceFlag,
    confidence: String(classification.confidence || 'LOW'),
    suggested_action: String(classification.suggested_human_action || ''),
  };

  if (intent === 'OPT_OUT') {
    fields.opted_out = true;
    fields.status = 'OPTED_OUT';
  } else if (intent === 'NO_SIGNAL') {
    // An out-of-office is recorded but never moves the resident or alerts anyone.
    fields.status = String(lease.status || 'SENT');
  } else if (requiresHuman) {
    fields.status = 'AT_RISK';
    fields.issue_status = 'OPEN';
    // A new grievance after a resolved one starts a fresh clock, otherwise
    // days_to_resolve would be measured from the previous, closed issue.
    const reopening = String(lease.issue_status || '') !== 'OPEN';
    fields.issue_opened_at = reopening ? nowIso : (lease.issue_opened_at || nowIso);
    if (reopening) fields.issue_resolved_at = null;
    fields.turnover_exposure = Number(selected.config && selected.config.avg_turnover_cost ? selected.config.avg_turnover_cost : 3900);
  } else {
    fields.status = 'STAYING';
  }

  writes.push({
    method: 'PATCH',
    table: 'Leases',
    body: { records: [{ id: lease.record_id, fields }], typecast: true },
  });

  const alertWorthy = requiresHuman && intent !== 'NO_SIGNAL';
  const cardLease = Object.assign({}, lease, fields, { record_id: lease.record_id });

  if (alertWorthy) {
    const card = atRiskAlertCard(cardLease, {});
    text = card.text;
    cardType = isCompliance ? 'atriskCompliance' : 'atrisk';
  } else {
    text = intent === 'NO_SIGNAL'
      ? 'Out-of-office reply logged for ' + lease.tenant_name + '. No action needed.'
      : 'Clean reply from ' + lease.tenant_name + ' (' + intent + '). Logged as a positive signal.';
    cardType = 'plain';
  }

  writes.push({
    method: 'POST',
    table: 'Outreach Log',
    body: {
      records: [{
        fields: {
          event_id: routed.event_id || ('reply-' + Date.now()),
          event_type: intent === 'NO_SIGNAL' ? 'NO_SIGNAL' : (intent === 'OPT_OUT' ? 'OPT_OUT' : 'REPLY_RECEIVED'),
          channel: 'EMAIL',
          direction: 'INBOUND',
          lease_id: lease.lease_id || '',
          tenant_name: lease.tenant_name || '',
          message_text: String(reply.reply_text || '').slice(0, 900),
          intent,
          grievance_category: fields.grievance_category,
          urgency: fields.urgency,
          compliance_flag: complianceFlag,
          confidence: fields.confidence,
          requires_human: requiresHuman,
          gmail_message_id: reply.message_id || '',
          created_at: nowIso,
        },
      }],
      typecast: true,
    },
  });
}

if (isUnmatched && !selected.duplicate) {
  writes.push({
    method: 'POST',
    table: 'Outreach Log',
    body: {
      records: [{
        fields: {
          event_id: routed.event_id || ('unmatched-' + Date.now()),
          event_type: 'UNMATCHED_REPLY',
          channel: 'EMAIL',
          direction: 'INBOUND',
          message_text: String(reply.reply_text || '').slice(0, 900),
          requires_human: true,
          gmail_message_id: reply.message_id || '',
          created_at: nowIso,
        },
      }],
      typecast: true,
    },
  });
}

if (selected.duplicate) {
  return [{
    json: {
      has_writes: false,
      card_type: 'none',
      chat_id: selected.chat_id,
      record_id: '',
      text: '',
      duplicate: true,
      processed_count: 0,
      alerted_count: 0,
      ok: true,
    },
  }];
}

return [{
  json: {
    writes,
    has_writes: writes.length > 0,
    card_type: cardType,
    chat_id: selected.chat_id,
    record_id: recordId,
    text,
    processed_count: 1,
    alerted_count: cardType.indexOf('atrisk') === 0 ? 1 : 0,
    unmatched: isUnmatched,
    waiting_count: selected.waiting_count || 0,
    ok: true,
  },
}];

const payload = $('Finalize Reply Route').first().json;
if (!payload.has_writes) return [];
return (payload.writes || []).map((write) => ({ json: write }));

const payload = $('Finalize Reply Route').first().json;
return [{
  json: {
    chat_id: payload.chat_id,
    text: payload.text,
    record_id: payload.record_id || '',
    card_type: payload.card_type || 'plain',
    processed_count: payload.processed_count || 0,
    alerted_count: payload.alerted_count || 0,
    waiting_count: payload.waiting_count || 0,
    unmatched: Boolean(payload.unmatched),
    ok: true,
  },
}];
